window.AVL_SOURCES = [{"label": "提交版（OJ 用）", "file": "repunit.py", "lang": "py", "stripped": "import sys\n\ndef gcd(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\ndef min_ones(m):\n    r = 0\n    limit = 9 * m + 2\n    n = 0\n    while n < limit:\n        n += 1\n        r = (r * 10 + 1) % m\n        if r == 0:\n            return n\n    return None\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\ndef to_int(tok):\n    try:\n        return int(tok)\n    except ValueError:\n        print(\"[!] invalid integer token: \" + repr(tok), file=sys.stderr)\n        return None\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:\n        return\n    t = to_int(tok)\n    if t is None:\n        return\n    if t < 0:\n        print(\"[!] negative case count T=\" + str(t), file=sys.stderr)\n        return\n    if t == 0:\n        return\n\n    answers = []\n\n    for case in range(1, t + 1):\n        tok = nxt()\n        if tok is None:\n            print(\"[!] EOF while reading m of case \" + str(case) + \"/\" + str(t),\n                  file=sys.stderr)\n            return\n        m = to_int(tok)\n        if m is None:\n            return\n\n        if m <= 0:\n            print(\"[!] invalid m=\" + str(m) + \" at case \" + str(case)\n                  + \" (m must be > 0)\", file=sys.stderr)\n            return\n        if gcd(m, 10) != 1:\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" is not coprime with 10 -> no such n exists\", file=sys.stderr)\n            return\n        if m >= 10000:\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" exceeds the stated range (m<10000); computing anyway\",\n                  file=sys.stderr)\n        if m > 1000000:\n\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" is too large to compute (limit 1000000)\", file=sys.stderr)\n            return\n\n        n = min_ones(m)\n        if n is None:\n            print(\"[!] no solution within 9m+2 steps for m=\" + str(m)\n                  + \" (data violates gcd(m,10)=1?)\", file=sys.stderr)\n            return\n\n        answers.append(n)\n\n    if answers:\n        out = []\n        for v in answers:\n            out.append(str(v))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n        sys.stdout.flush()\n\n    if has_buffered():\n        print(\"[!] extra token(s) after \" + str(t) + \" case(s) -- \"\n              \"题面第 1 行是 T 组数，但同一行还有多余数据，请核对判题格式\",\n              file=sys.stderr)\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n#\n# n 个 1 —— OJ 提交版（stdout 只输出答案）\n# ==========================================\n# 输入：第 1 行 T（组数，T<20），随后 T 个整数 m（0<m<10000，且 gcd(m,10)=1）。\n# 输出：每个 m 一行，打印最小的 n，使 A_n = 11...1（n 个 1）能被 m 整除。\n#       **读完 T 组、全部算完之后，一次性把答案打出来**（不是边算边打）。\n#\n# 判题格式依据（铁律 2）：\n#   * 题面写明\"第一行是一个整数 T，表示测试数据的组数\" -> **给定组数**型\n#     （不是 EOF、也不是哨兵）。样例首行 3 后面正好 3 个 m。\n#   * 样例输出 3 行、**没有 Case i 前缀**，每个 m 对应一行。\n#     （同题集的 LCS 也是 T 组，但它每组要 2 行、还有 Case 前缀 —— 逐题核对别照抄。）\n#\n# 算法（秦九韶 / Horner —— 题面提示说的就是这个）：\n#   千万别去构造 11...1 这个巨大的数，只留它除以 m 的**余数**：\n#       r_0 = 0\n#       r_n = (10 * r_{n-1} + 1) % m        <- 等于\"把下一个 1 添到末尾\"\n#   第一个 r_n == 0 的 n 就是答案。\n#   依据：A_n = 10*A_{n-1} + 1，而 (10x+1) mod m 只取决于 x mod m。\n#\n# 【注意】 关于\"模 9m 还是模 m\"（本题最容易想错的一处）：\n#   A_n = (10^n - 1) / 9，所以 A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m) ——\n#   因为要两边同乘 9 才能把除法消掉。**不能**写成\"10^n ≡ 1 (mod m)\"：\n#   m=3 时 ord_3(10)=1 会答 1，而 A_1=1 根本不被 3 整除，正解是 3（111=3×37）；\n#   m=9 时同理，正解是 9 而不是 1。\"9\" 这个因子是 A_n 的分母带出来的。\n#   好在提交版不用显式写 9m：逐位取余 r=(10r+1)%m 与它等价。\n#\n# 循环为什么一定终止：gcd(m,10)=1 => 10 在模 9m 的乘法群里有阶，\n#   n = ord_{9m}(10) 必存在且整除 φ(9m) ≤ 9m。所以上界取 9m 是**可证安全**的\n#   （m<10000 时实测最坏 m=9981 -> n=9972，远没到界）。\n#\n# 复杂度：O(n) 时间、O(1) 空间（n 最坏 9972，20 组也就 20 万次取余）。\n\nimport sys\n\n\ndef gcd(a, b):\n    \"\"\"欧几里得算法。手写而不用 math.gcd —— 老 OJ 的 Python 版本不好赌。\"\"\"\n    while b:\n        a, b = b, a % b\n    return a\n\n\ndef min_ones(m):\n    \"\"\"返回最小的 n，使 11...1（n 个 1）能被 m 整除；越界返回 None。\n\n    只维护余数，不构造大数：构造 11...1 在 n 上千位时既慢，又会撞上\n    Python 3.11+ 的 int<->str 位数限制（本仓库新踩的坑）。\n    \"\"\"\n    r = 0\n    limit = 9 * m + 2                      # 阶必整除 φ(9m) ≤ 9m，留 2 步余量\n    n = 0\n    while n < limit:\n        n += 1\n        r = (r * 10 + 1) % m\n        if r == 0:\n            return n\n    return None                            # 只有数据不合法（gcd(m,10)≠1）才会到这\n\n\ndef make_reader():\n    \"\"\"返回 (nxt, has_buffered)。\n\n    nxt：每次吐一个 token，取完返回 None。\n    统一用 readline() 逐行读 —— 终端 / PyCharm / OJ 三种环境都对，\n    不做任何 isatty 判断（PyCharm 的 stdin 不是真 tty，会踩空）。\n\n    【注意】 取 token 用「反序入栈 + pop()」，不要 `buf.pop(0)`：后者每次 memmove\n    整个缓冲，几十万 token 挤在同一行时退化成 O(k^2)（本仓库陷阱 25）。\n\n    【注意】 为什么要把 has_buffered 交出去：T 组题读满 T 组后若还想\"看看有没有多余\n    数据\"，**只能查缓冲区、绝不能再去 readline()** —— 终端里那会一直等你敲键盘，\n    表现为\"答案都打完了程序却不结束\"（本仓库旧写法踩过，`11的余数` 已改成这个做法）。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\n\ndef to_int(tok):\n    \"\"\"把 token 转成 int；失败时按仓库规范打 [!] 到 stderr 并返回 None。\"\"\"\n    try:\n        return int(tok)\n    except ValueError:\n        print(\"[!] invalid integer token: \" + repr(tok), file=sys.stderr)\n        return None\n\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:                        # 空输入\n        return\n    t = to_int(tok)\n    if t is None:\n        return\n    if t < 0:\n        print(\"[!] negative case count T=\" + str(t), file=sys.stderr)\n        return\n    if t == 0:                             # 0 组：什么都不输出\n        return\n\n    answers = []\n\n    for case in range(1, t + 1):\n        tok = nxt()\n        if tok is None:\n            print(\"[!] EOF while reading m of case \" + str(case) + \"/\" + str(t),\n                  file=sys.stderr)\n            return\n        m = to_int(tok)\n        if m is None:\n            return\n\n        # 这两类**不能**继续往下算：m≤0 无意义；gcd(m,10)≠1 时解根本不存在\n        # （11...1 恒为奇数、末位非 0 非 5），硬算会把伪答案打进 stdout（铁律 6）。\n        if m <= 0:\n            print(\"[!] invalid m=\" + str(m) + \" at case \" + str(case)\n                  + \" (m must be > 0)\", file=sys.stderr)\n            return\n        if gcd(m, 10) != 1:\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" is not coprime with 10 -> no such n exists\", file=sys.stderr)\n            return\n        if m >= 10000:                     # 题面范围外，但公式照样成立 -> 提示后继续算\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" exceeds the stated range (m<10000); computing anyway\",\n                  file=sys.stderr)\n        if m > 1000000:\n            # 再大就不是\"算得出来\"的事了：9m 步在解释器里要跑几十秒，比 TLE 更糟的是\n            # 看起来卡死。与其硬撑着跑，不如明确中止（铁律 6：宁可中止也不能错答）。\n            print(\"[!] m=\" + str(m) + \" at case \" + str(case)\n                  + \" is too large to compute (limit 1000000)\", file=sys.stderr)\n            return\n\n        n = min_ones(m)\n        if n is None:\n            print(\"[!] no solution within 9m+2 steps for m=\" + str(m)\n                  + \" (data violates gcd(m,10)=1?)\", file=sys.stderr)\n            return\n\n        answers.append(n)                  # 先攒着，读完 T 组再一起输出\n\n    # ---- 一起输出（\"一次性输入、一次性输出\"）----\n    # 为什么攒完再打，而不是边算边 print：\n    #   * 终端里输入与输出不再交错，读起来清爽（这是题面样例给人的感觉）\n    #   * 中途遇到坏数据直接 return，**stdout 一个字节都没写过**，\n    #     不会出现\"前两组答案已打出去、第三组才报错\"的半截输出\n    # 行尾换行照铁律 4：join 之后补一个 \"\\n\"（对齐 cout << ans << endl）。\n    if answers:\n        out = []\n        for v in answers:\n            out.append(str(v))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n        sys.stdout.flush()\n\n    # 读完 T 组后若缓冲区里还堆着 token，说明格式可能不是\"T 组\"，\n    # 提示出来便于人工核对。**不读新行**（否则终端里会卡住不退出），\n    # stdout 依然纯净，不影响判题。\n    # 【注意】这个检查的能力边界：只能看见**与最后一个 token 同一行**的多余数据。\n    # 换行写在后面的多余数据看不到 —— 想知道就得再 readline()，而那样终端里会卡住。\n    # 换句话说：它是个\"顺手提醒\"，不是格式校验器。\n    if has_buffered():\n        print(\"[!] extra token(s) after \" + str(t) + \" case(s) -- \"\n              \"题面第 1 行是 T 组数，但同一行还有多余数据，请核对判题格式\",\n              file=sys.stderr)\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "详细版（本地学习）", "file": "repunit_detailed.py", "lang": "py", "stripped": "import sys\n\nSTEP_HEAD = 12\nSTEP_TAIL = 8\nDIGIT_PREVIEW = 12\n\ndef gcd(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\ndef horner_steps(m):\n    r = 0\n    remainders = []\n    limit = 9 * m + 2\n    while len(remainders) < limit:\n        r = (r * 10 + 1) % m\n        remainders.append(r)\n        if r == 0:\n            return len(remainders), remainders\n    return None, remainders\n\ndef first_hit_by_bigint(m, n):\n    v = 0\n    first = None\n    for k in range(1, n + 1):\n        v = v * 10 + 1\n        if first is None and v % m == 0:\n            first = k\n    return first, v\n\ndef preview_bigint(v, n):\n    if n <= 2 * DIGIT_PREVIEW:\n        return str(v)\n    head = v // (10 ** (n - DIGIT_PREVIEW))\n    tail = v % (10 ** DIGIT_PREVIEW)\n    return (str(head) + \"…（中间省略 \" + str(n - 2 * DIGIT_PREVIEW)\n            + \" 位）…\" + str(tail).rjust(DIGIT_PREVIEW, \"0\"))\n\ndef factorize(x):\n    f = {}\n    d = 2\n    while d * d <= x:\n        while x % d == 0:\n            f[d] = f.get(d, 0) + 1\n            x //= d\n        d += 1\n    if x > 1:\n        f[x] = f.get(x, 0) + 1\n    return f\n\ndef phi_of(x):\n    r = x\n    for p in factorize(x):\n        r = r // p * (p - 1)\n    return r\n\ndef order_of_ten(m):\n    mod = 9 * m\n    phi = mod\n    for p in factorize(mod):\n        phi = phi // p * (p - 1)\n    n = phi\n    for p in factorize(phi):\n        while n % p == 0 and pow(10, n // p, mod) == 1:\n            n //= p\n    return n\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\ndef to_int(tok):\n    try:\n        return int(tok)\n    except ValueError:\n        print(\"[!] invalid integer token: \" + repr(tok), file=sys.stderr)\n        return None\n\ndef print_chain(m, n, remainders):\n    total = len(remainders)\n    print(\"\")\n    print(\"  秦九韶余数链（r_n = (10·r_{n-1} + 1) mod \" + str(m) + \"）：\")\n    if total <= STEP_HEAD + STEP_TAIL:\n        idxs = list(range(total))\n    else:\n        idxs = list(range(STEP_HEAD)) + list(range(total - STEP_TAIL, total))\n    last = -1\n    for i in idxs:\n        if i != last + 1:\n            print(\"    …… 中间省略 \" + str(i - last - 1) + \" 步 ……\")\n        r = remainders[i]\n        tag = \"\"\n        if r == 0:\n            tag = \"   <== 第一次整除！n = \" + str(i + 1)\n        elif i + 1 == n:\n            tag = \"\"\n        print(\"    n = \" + str(i + 1).rjust(6) + \"   r = \" + str(r))\n        if tag:\n            print(\"    \" + tag.strip())\n        last = i\n\ndef main():\n    nxt = make_reader()\n    answers = []\n\n    tok = nxt()\n    if tok is None:\n        return\n    t = to_int(tok)\n    if t is None:\n        return\n    if t < 0:\n        print(\"[!] negative case count T=\" + str(t), file=sys.stderr)\n        return\n    if t == 0:\n        return\n\n    for case in range(1, t + 1):\n        tok = nxt()\n        if tok is None:\n            print(\"[!] EOF while reading m of case \" + str(case), file=sys.stderr)\n            return\n        m = to_int(tok)\n        if m is None:\n            return\n        if m <= 0 or gcd(m, 10) != 1:\n            print(\"[!] invalid m=\" + str(m) + \" at case \" + str(case)\n                  + \" (need m>0 and gcd(m,10)=1)\", file=sys.stderr)\n            return\n\n        n, remainders = horner_steps(m)\n\n        print(\"\")\n        print(\"=\" * 58)\n        print(\"第 \" + str(case) + \" 组：m = \" + str(m))\n\n        if n is None:\n            print(\"  9m+2 步内没找到解 —— 数据不满足 gcd(m,10)=1？\")\n            print(\"[!] no solution for m=\" + str(m), file=sys.stderr)\n            return\n\n        print(\"\")\n        print(\"  ① 秦九韶逐位取余：A_n = 10·A_{n-1} + 1，只留余数\")\n        print_chain(m, n, remainders)\n\n        first_hit, big = first_hit_by_bigint(m, n)\n        ok_div = (big % m == 0)\n        ok_min = (first_hit == n)\n        print(\"\")\n        print(\"  ② 真算大整数核对（把 11…1 老实构造出来，不走字符串转换）：\")\n        print(\"     A_\" + str(n) + \" = \" + preview_bigint(big, n))\n        print(\"     共 \" + str(n) + \" 位；A_\" + str(n) + \" mod m = \" + str(big % m)\n              + \"  ->  \" + (\"OK 整除\" if ok_div else \"MISMATCH 不整除！\"))\n        print(\"     最小性：从 1 位一路除到 \" + str(n) + \" 位，第一个能整除的是 \"\n              + str(first_hit) + \"  ->  \"\n              + (\"OK 正是 n，确实最小\" if ok_min else \"MISMATCH 更小的位数也能整除！\"))\n\n        m9 = 9 * m\n        ord10 = order_of_ten(m)\n        ok_order = (ord10 == n)\n        print(\"\")\n        print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m)\")\n\n        print(\"     模数 9m = \" + str(m9) + \"，φ(9m) = \" + str(phi_of(m9))\n              + \"（阶必整除它）\")\n        print(\"     10 在模 \" + str(m9) + \" 下的阶 = \" + str(ord10)\n              + \"  ->  \" + (\"OK 与 ① 一致\" if ok_order else \"MISMATCH！\"))\n\n        all_ok = ok_div and ok_min and ok_order\n        print(\"\")\n        print(\"  Sum check: ① 得到 n=\" + str(n)\n              + \"；② 真算整除 + 最小性 \" + (\"OK\" if (ok_div and ok_min) else \"FAILED\")\n              + \"；③ 阶=\" + str(ord10) + \" \" + (\"OK\" if ok_order else \"FAILED\")\n              + \"  =>  \" + (\"ALL OK\" if all_ok else \"FAILED\"))\n        if not all_ok:\n            print(\"[!] Sum check FAILED on case \" + str(case), file=sys.stderr)\n\n        sys.stdout.flush()\n        answers.append(n)\n\n    if answers:\n        print(\"\")\n        print(\"=\" * 58)\n        print(\"按 OJ 格式统一输出（与 repunit.py 一致：全部读完再一次性输出）：\")\n        out = []\n        for v in answers:\n            out.append(str(v))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n        sys.stdout.flush()\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n\"\"\"\nn 个 1 - Detailed Version\n========================\n【注意】 仅本地学习用 —— 请勿提交本文件到 OJ！它输出余数链、真值核对与阶核对，\n   真正要提交的是同目录下的 repunit.py（只输出每组的 n）。\n   文件末尾虽也按 OJ 格式再打了一遍答案，但前面的内容会让判题直接 WA。\n\n输入格式与提交版一致：第 1 行 T（组数），随后 T 个整数 m。\n\n三条**互相独立**的路，互相对账（Sum check）：\n  ① 秦九韶逐位取余（= 提交版算法）：r_n = (10*r_{n-1} + 1) % m，首个 r_n = 0 即答案\n  ② 真算大整数：把 11...1 这个 n 位数**老实构造出来**（逐位累乘），\n     验证 A_n % m == 0；**最小性从 1 位一路核到 n 位**（不是只比 A_{n-1} ——\n     那只是\"局部最小\"，m=3 会放过 n=6 这种错答案）\n  ③ 乘法阶：n 应等于 ord_{9m}(10)。先取 φ(9m)，再用其质因子逐个往下除\n     （10 在模 9m 的乘法群里的阶 —— 与 ① 完全不同的思路）\n\n【注意】 ② 里的构造**绝不能写成 int(\"1\" * n)**：Python 3.11+ 默认禁止\n   int<->str 转换超过 4300 位，而本题 n 可达 9972（m=9981），直接抛 ValueError。\n   同理，打印这个巨数时也不能 str()：只取首尾各若干位。\n\"\"\"\n\nimport sys\n\nSTEP_HEAD = 12          # 余数链开头打印这么多步\nSTEP_TAIL = 8           # 结尾打印这么多步（中间省略）\nDIGIT_PREVIEW = 12      # 首/尾各预览多少位数字\n\n\ndef gcd(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\n\ndef horner_steps(m):\n    \"\"\"走一遍秦九韶。返回 (n, remainders)。\n\n    remainders[k] = A_{k+1} % m，即\"k+1 个 1\"的余数；n 是首个使余数为 0 的步数。\n    无解返回 (None, remainders)。\n    \"\"\"\n    r = 0\n    remainders = []\n    limit = 9 * m + 2\n    while len(remainders) < limit:\n        r = (r * 10 + 1) % m\n        remainders.append(r)\n        if r == 0:\n            return len(remainders), remainders\n    return None, remainders\n\n\ndef first_hit_by_bigint(m, n):\n    \"\"\"真大整数从 1 位做到 n 位：返回 (第一个能被 m 整除的位数, n 位的 A_n)。\n\n    【注意】 两件事一起做，不再单独留一个\"只构造不判断\"的函数 ——\n       那种函数一旦被别处取代就成了**打不掉任何变异的冗余代码**（本仓库陷阱 29）。\n\n    【注意】 逐位累乘，**不用 `int(\"1\" * n)`**：Python 3.11+ 把 int<->str 转换默认限制在\n       4300 位，而本题 n 可达 9972，那行会直接抛 ValueError（本仓库新踩的坑）。\n\n    【注意】 最小性**不能**只比 A_{n-1}：m=3、n=6 时 A_6 能被 3 整除、A_5 不能，\n       可真正的最小值是 **3**（A_3 = 111 = 3×37）。只比前一项得到的是\"局部最小\"，\n       会对着一个错答案报 OK —— 本仓库陷阱 20/26 说的装饰性断言就是这类。\n       所以必须**每一位都核**。\n    \"\"\"\n    v = 0\n    first = None\n    for k in range(1, n + 1):\n        v = v * 10 + 1\n        if first is None and v % m == 0:\n            first = k\n    return first, v\n\n\ndef preview_bigint(v, n):\n    \"\"\"巨数的首尾预览（同样避开 str 限制）。返回一句描述。\"\"\"\n    if n <= 2 * DIGIT_PREVIEW:\n        return str(v)                       # 位数很少，直接 str 没问题\n    head = v // (10 ** (n - DIGIT_PREVIEW))\n    tail = v % (10 ** DIGIT_PREVIEW)\n    return (str(head) + \"…（中间省略 \" + str(n - 2 * DIGIT_PREVIEW)\n            + \" 位）…\" + str(tail).rjust(DIGIT_PREVIEW, \"0\"))\n\n\ndef factorize(x):\n    \"\"\"质因数分解（x 很小，试除足够）。返回 {质因子: 次数}。\"\"\"\n    f = {}\n    d = 2\n    while d * d <= x:\n        while x % d == 0:\n            f[d] = f.get(d, 0) + 1\n            x //= d\n        d += 1\n    if x > 1:\n        f[x] = f.get(x, 0) + 1\n    return f\n\n\ndef phi_of(x):\n    \"\"\"欧拉函数 φ(x)。x 很小，试除足够。\"\"\"\n    r = x\n    for p in factorize(x):\n        r = r // p * (p - 1)\n    return r\n\n\ndef order_of_ten(m):\n    \"\"\"用乘法阶算 n = ord_{9m}(10)（**独立于** ① 的逐位取余）。\n\n    A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m)，所以 n 就是 10 在模 9m 下的阶。\n    做法：先取 φ(9m)（阶必整除它），再把 φ 的每个质因子逐个试除下去。\n    \"\"\"\n    mod = 9 * m\n    phi = mod\n    for p in factorize(mod):\n        phi = phi // p * (p - 1)\n    n = phi\n    for p in factorize(phi):\n        while n % p == 0 and pow(10, n // p, mod) == 1:\n            n //= p\n    return n\n\n\ndef make_reader():\n    \"\"\"每次吐一个 token，取完返回 None（与提交版同一套读法）。\"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\n\ndef to_int(tok):\n    try:\n        return int(tok)\n    except ValueError:\n        print(\"[!] invalid integer token: \" + repr(tok), file=sys.stderr)\n        return None\n\n\ndef print_chain(m, n, remainders):\n    \"\"\"打印余数链（太长就掐头去尾）。\"\"\"\n    total = len(remainders)\n    print(\"\")\n    print(\"  秦九韶余数链（r_n = (10·r_{n-1} + 1) mod \" + str(m) + \"）：\")\n    if total <= STEP_HEAD + STEP_TAIL:\n        idxs = list(range(total))\n    else:\n        idxs = list(range(STEP_HEAD)) + list(range(total - STEP_TAIL, total))\n    last = -1\n    for i in idxs:\n        if i != last + 1:\n            print(\"    …… 中间省略 \" + str(i - last - 1) + \" 步 ……\")\n        r = remainders[i]\n        tag = \"\"\n        if r == 0:\n            tag = \"   <== 第一次整除！n = \" + str(i + 1)\n        elif i + 1 == n:\n            tag = \"\"\n        print(\"    n = \" + str(i + 1).rjust(6) + \"   r = \" + str(r))\n        if tag:\n            print(\"    \" + tag.strip())\n        last = i\n\n\ndef main():\n    nxt = make_reader()\n    answers = []\n\n    tok = nxt()\n    if tok is None:\n        return\n    t = to_int(tok)\n    if t is None:\n        return\n    if t < 0:\n        print(\"[!] negative case count T=\" + str(t), file=sys.stderr)\n        return\n    if t == 0:\n        return\n\n    for case in range(1, t + 1):\n        tok = nxt()\n        if tok is None:\n            print(\"[!] EOF while reading m of case \" + str(case), file=sys.stderr)\n            return\n        m = to_int(tok)\n        if m is None:\n            return\n        if m <= 0 or gcd(m, 10) != 1:\n            print(\"[!] invalid m=\" + str(m) + \" at case \" + str(case)\n                  + \" (need m>0 and gcd(m,10)=1)\", file=sys.stderr)\n            return\n\n        n, remainders = horner_steps(m)\n\n        print(\"\")\n        print(\"=\" * 58)\n        print(\"第 \" + str(case) + \" 组：m = \" + str(m))\n\n        if n is None:\n            print(\"  9m+2 步内没找到解 —— 数据不满足 gcd(m,10)=1？\")\n            print(\"[!] no solution for m=\" + str(m), file=sys.stderr)\n            return\n\n        # ---------- ① 秦九韶 ----------\n        print(\"\")\n        print(\"  ① 秦九韶逐位取余：A_n = 10·A_{n-1} + 1，只留余数\")\n        print_chain(m, n, remainders)\n\n        # ---------- ② 真算大整数（含最小性）----------\n        first_hit, big = first_hit_by_bigint(m, n)\n        ok_div = (big % m == 0)\n        ok_min = (first_hit == n)\n        print(\"\")\n        print(\"  ② 真算大整数核对（把 11…1 老实构造出来，不走字符串转换）：\")\n        print(\"     A_\" + str(n) + \" = \" + preview_bigint(big, n))\n        print(\"     共 \" + str(n) + \" 位；A_\" + str(n) + \" mod m = \" + str(big % m)\n              + \"  ->  \" + (\"OK 整除\" if ok_div else \"MISMATCH 不整除！\"))\n        print(\"     最小性：从 1 位一路除到 \" + str(n) + \" 位，第一个能整除的是 \"\n              + str(first_hit) + \"  ->  \"\n              + (\"OK 正是 n，确实最小\" if ok_min else \"MISMATCH 更小的位数也能整除！\"))\n\n        # ---------- ③ 乘法阶 ----------\n        m9 = 9 * m\n        ord10 = order_of_ten(m)\n        ok_order = (ord10 == n)\n        print(\"\")\n        print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m)\")\n        # 【注意】这里原来是 `... __globals__[\"_phi_cache\"][0]) if False else \"\"`：\n        # 标签承诺打印 φ(9m)，实际恒打印空串（`_phi_cache` 这个全局压根不存在，\n        # 一旦有人把 if False 翻成真就 KeyError）。本轮改成**真的算**。\n        print(\"     模数 9m = \" + str(m9) + \"，φ(9m) = \" + str(phi_of(m9))\n              + \"（阶必整除它）\")\n        print(\"     10 在模 \" + str(m9) + \" 下的阶 = \" + str(ord10)\n              + \"  ->  \" + (\"OK 与 ① 一致\" if ok_order else \"MISMATCH！\"))\n\n        all_ok = ok_div and ok_min and ok_order\n        print(\"\")\n        print(\"  Sum check: ① 得到 n=\" + str(n)\n              + \"；② 真算整除 + 最小性 \" + (\"OK\" if (ok_div and ok_min) else \"FAILED\")\n              + \"；③ 阶=\" + str(ord10) + \" \" + (\"OK\" if ok_order else \"FAILED\")\n              + \"  =>  \" + (\"ALL OK\" if all_ok else \"FAILED\"))\n        if not all_ok:\n            print(\"[!] Sum check FAILED on case \" + str(case), file=sys.stderr)\n\n        sys.stdout.flush()\n        answers.append(n)\n\n    # 全部处理完，再按提交版的\"一起输出\"格式统一打一遍纯答案\n    # （与 repunit.py 行为一致：读完 T 组、算完，一次性 write，行尾带换行）\n    if answers:\n        print(\"\")\n        print(\"=\" * 58)\n        print(\"按 OJ 格式统一输出（与 repunit.py 一致：全部读完再一次性输出）：\")\n        out = []\n        for v in answers:\n            out.append(str(v))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n        sys.stdout.flush()\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "C 实现", "file": "repunit.c", "lang": "c", "stripped": "#include <stdio.h>\n\n#define M_LIMIT 1000000\n#define ANS_MAX 1024\n\nstatic int gcd_int(int a, int b)\n{\n    int t;\n    while (b != 0) {\n        t = a % b;\n        a = b;\n        b = t;\n    }\n    return a;\n}\n\nint main(void)\n{\n    int t, case_i, i, m, n, r;\n    static int ans[ANS_MAX];\n\n    if (scanf(\"%d\", &t) != 1) {\n        return 0;\n    }\n    if (t < 0) {\n        fprintf(stderr, \"[!] negative case count T=%d\\n\", t);\n        return 1;\n    }\n    if (t == 0) {\n        return 0;\n    }\n    if (t > ANS_MAX) {\n        fprintf(stderr, \"[!] T=%d too large to buffer (limit %d)\\n\", t, ANS_MAX);\n        return 1;\n    }\n\n    for (case_i = 1; case_i <= t; case_i++) {\n        if (scanf(\"%d\", &m) != 1) {\n            fprintf(stderr, \"[!] EOF while reading m of case %d/%d\\n\", case_i, t);\n            return 1;\n        }\n        if (m <= 0 || gcd_int(m, 10) != 1) {\n            fprintf(stderr, \"[!] invalid m=%d at case %d (need m>0, gcd(m,10)=1)\\n\",\n                    m, case_i);\n            return 1;\n        }\n        if (m >= 10000) {\n            fprintf(stderr, \"[!] m=%d exceeds the stated range (m<10000); computing anyway\\n\", m);\n        }\n        if (m > M_LIMIT) {\n            fprintf(stderr, \"[!] m=%d is too large to compute (limit %d)\\n\",\n                    m, M_LIMIT);\n            return 1;\n        }\n\n        r = 0;\n        n = 0;\n        while (n < 9 * m + 2) {\n            n++;\n            r = (r * 10 + 1) % m;\n            if (r == 0) {\n                break;\n            }\n        }\n        if (r != 0) {\n            fprintf(stderr, \"[!] no solution within 9m+2 steps for m=%d\\n\", m);\n            return 1;\n        }\n\n        ans[case_i - 1] = n;\n    }\n\n\n    for (i = 0; i < t; i++) {\n        printf(\"%d\\n\", ans[i]);\n    }\n    fflush(stdout);\n\n    return 0;\n}\n", "original": "/* n 个 1 —— C 实现（OJ 兼容版）\n *\n * ⚠️ 本机没有任何 C 编译器（gcc/clang/tcc/cl/zig 全无），\n *    本文件**从未编译验证**，交付时须如实说明。\n *    逻辑与同目录 repunit.py 等价：秦九韶逐位取余，只留余数、不构造大数。\n *\n * 输入：第 1 行 T（组数，T<20），随后 T 个整数 m（0<m<10000，gcd(m,10)=1）。\n * 输出：每个 m 一行，最小的 n 使 11...1（n 个 1）能被 m 整除。\n *       **读完 T 组、全部算完之后一次性输出**（与 repunit.py 的\"一起输入、一起输出\"一致）。\n * 错误一律走 stderr、前缀 [!]；stdout 只留答案。\n *\n * 写法按 C89 保守写（变量都声明在块首），老 OJ 的编译器也不会挡。\n *\n * ⚠️ 已知与 repunit.py 的行为差异（对**合法**输入逐字节一致）：\n *    1) scanf(\"%d\") 是「前缀式」解析：读到非数字时它不消费输入、只返回 0/EOF，\n *       所以脏数据下 C 版会打 [!] 并停止，与 Python 版的提示位置可能不同。\n *       本仓库陷阱 13 要求改成 fgets + strtol 并校验 token 被完整消费 ——\n *       但**本机无编译器**，改完无从验证，反而更危险；故保持现状并如实标注。\n *    2) 退出码：**0 = 正常结束**，**1 = 数据有问题**；Python 版恒为 0（错误只走 stderr）。\n *    3) 本题是\"给定 T 组\"，所以收尾**不做**\"有没有多余数据\"的检查 ——\n *       C 里再 scanf 一次会阻塞在终端上（Python 版靠缓冲区判断，不需要再读）。\n *\n * 循环上界：n = ord_{9m}(10) 必整除 φ(9m) ≤ 9m，所以 9m+2 步内必有解或数据非法。\n *   （**不能**用 ord_m(10)：A_n = (10^n-1)/9，要同乘 9 才是模 9m；\n *     m=3 时模 m 会答 1，正解是 3。）\n */\n\n#include <stdio.h>\n\n#define M_LIMIT 1000000        /* 超出就别算了：9m 步会跑到\"看起来卡死\" */\n#define ANS_MAX 1024           /* 答案缓冲上限（题面 T<20，纯属防越界） */\n\nstatic int gcd_int(int a, int b)\n{\n    int t;\n    while (b != 0) {\n        t = a % b;\n        a = b;\n        b = t;\n    }\n    return a;\n}\n\nint main(void)\n{\n    int t, case_i, i, m, n, r;\n    static int ans[ANS_MAX];              /* 攒答案用：读完 T 组再一起输出 */\n\n    if (scanf(\"%d\", &t) != 1) {           /* 空输入 */\n        return 0;\n    }\n    if (t < 0) {\n        fprintf(stderr, \"[!] negative case count T=%d\\n\", t);\n        return 1;\n    }\n    if (t == 0) {                         /* 0 组：什么都不输出 */\n        return 0;\n    }\n    if (t > ANS_MAX) {                    /* 题面 T<20；这里只是防越界写 */\n        fprintf(stderr, \"[!] T=%d too large to buffer (limit %d)\\n\", t, ANS_MAX);\n        return 1;\n    }\n\n    for (case_i = 1; case_i <= t; case_i++) {\n        if (scanf(\"%d\", &m) != 1) {\n            fprintf(stderr, \"[!] EOF while reading m of case %d/%d\\n\", case_i, t);\n            return 1;\n        }\n        if (m <= 0 || gcd_int(m, 10) != 1) {\n            fprintf(stderr, \"[!] invalid m=%d at case %d (need m>0, gcd(m,10)=1)\\n\",\n                    m, case_i);\n            return 1;\n        }\n        if (m >= 10000) {\n            fprintf(stderr, \"[!] m=%d exceeds the stated range (m<10000); computing anyway\\n\", m);\n        }\n        if (m > M_LIMIT) {\n            fprintf(stderr, \"[!] m=%d is too large to compute (limit %d)\\n\",\n                    m, M_LIMIT);\n            return 1;\n        }\n\n        r = 0;\n        n = 0;\n        while (n < 9 * m + 2) {           /* 阶必 ≤ φ(9m) ≤ 9m，留 2 步余量 */\n            n++;\n            r = (r * 10 + 1) % m;\n            if (r == 0) {\n                break;\n            }\n        }\n        if (r != 0) {                     /* 只有数据不合法（gcd(m,10)≠1）才会到这 */\n            fprintf(stderr, \"[!] no solution within 9m+2 steps for m=%d\\n\", m);\n            return 1;\n        }\n\n        ans[case_i - 1] = n;              /* 先攒着，别急着打 */\n    }\n\n    /* 全部读完再一起输出 —— 与 repunit.py 的\"一起输入、一起输出\"行为一致。\n       好处：中途遇到坏数据时上面就 return 了，stdout 一个字节都没写过，\n       不会出现\"前几组答案已打出去、后面才报错\"的半截输出。 */\n    for (i = 0; i < t; i++) {\n        printf(\"%d\\n\", ans[i]);\n    }\n    fflush(stdout);\n\n    return 0;\n}\n"}, {"label": "验证脚本 verify_repunit.py", "file": "verify_repunit.py", "lang": "py", "stripped": "import importlib.util\nimport os\nimport subprocess\nimport sys\nimport time\n\nsys.dont_write_bytecode = True\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSUBMISSION = os.path.join(HERE, \"repunit.py\")\n\ndef _load(fname, modname):\n    spec = importlib.util.spec_from_file_location(modname, os.path.join(HERE, fname))\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\nmini = _load(\"repunit.py\", \"repunit_under_test\")\ndetailed = _load(\"repunit_detailed.py\", \"repunit_detailed_under_test\")\n\nsolve = mini.min_ones\ngcd_own = mini.gcd\n\nREP_CACHE = [0]\n\ndef rep(n):\n    while len(REP_CACHE) <= n:\n        REP_CACHE.append(REP_CACHE[-1] * 10 + 1)\n    return REP_CACHE[n]\n\ndef rep_direct(n):\n    v = 0\n    for _ in range(n):\n        v = v * 10 + 1\n    return v\n\ndef brute_true(m, limit):\n    for n in range(1, limit + 1):\n        if rep(n) % m == 0:\n            return n\n    return None\n\ndef gcd_ref(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\ndef factorize(x):\n    f = {}\n    d = 2\n    while d * d <= x:\n        while x % d == 0:\n            f[d] = f.get(d, 0) + 1\n            x //= d\n        d += 1\n    if x > 1:\n        f[x] = f.get(x, 0) + 1\n    return f\n\ndef order_by_phi(m):\n    mod = 9 * m\n    phi = mod\n    for p in factorize(mod):\n        phi = phi // p * (p - 1)\n    n = phi\n    for p in factorize(phi):\n        while n % p == 0 and pow(10, n // p, mod) == 1:\n            n //= p\n    return n\n\ndef is_minimal_order(m, n):\n    mod = 9 * m\n    if pow(10, n, mod) != 1:\n        return False\n    for p in factorize(n):\n        if pow(10, n // p, mod) == 1:\n            return False\n    return True\n\nANCHORS = [\n    (3, 3, \"★ 模 m 的错法会答 1：A_1=1 不被 3 整除，A_3=111=3×37\"),\n    (9, 9, \"★ 同上：A_9=111111111 是 9 的倍数，最小的就是这个 n=9\"),\n    (1111, 4, \"题面样例：1111 = 1111×1\"),\n    (2023, 816, \"题面样例：n=816\"),\n    (1, 1, \"m=1：1 能被 1 整除\"),\n    (11, 2, \"A_2 = 11\"),\n    (7, 6, \"A_6 = 111111 = 7×15873\"),\n    (13, 6, \"A_6 = 111111 = 13×8547\"),\n    (37, 3, \"A_3 = 111 = 37×3\"),\n    (41, 5, \"A_5 = 11111 = 41×271\"),\n    (101, 4, \"A_4 = 1111 = 101×11\"),\n    (9981, 9972, \"题面范围内实测最坏：n=9972（循环上界的依据）\"),\n]\n\nWORST19 = (9981, 9973, 9967, 9963, 9949, 9941, 9937, 9931, 9929, 9923, 9919,\n           9901, 9887, 9879, 9877, 9871, 9863, 9859, 9857)\n\ndef subprocess_cases():\n    sample = \"3\\n3\\n1111\\n2023\\n\"\n    return [\n        (\"题面样例\", sample, \"3\\n4\\n816\\n\", True, None),\n        (\"CRLF\", sample.replace(\"\\n\", \"\\r\\n\"), \"3\\n4\\n816\\n\", True, None),\n        (\"数同行 + 多空行\", \"\\n2 3 1111\\n\\n\", \"3\\n4\\n\", True, None),\n        (\"末尾无换行\", \"3\\n3\\n1111\\n2023\", \"3\\n4\\n816\\n\", True, None),\n        (\"T=0 -> 无输出\", \"0\\n\", \"\", True, None),\n        (\"单组 m=1\", \"1\\n1\\n\", \"1\\n\", True, None),\n        (\"最坏一组 m=9981\", \"1\\n9981\\n\", \"9972\\n\", True, None),\n\n        (\"19 组最坏\", \"19\\n\" + \"\".join(\"%d\\n\" % x for x in WORST19),\n         \"\".join(\"%d\\n\" % order_by_phi(x) for x in WORST19), True, None),\n        (\"同行多余数据 -> 提示但不影响 stdout\", \"2 3 1111 9999\\n\", \"3\\n4\\n\", False,\n         \"extra token\"),\n\n        (\"m=10001 超范围 -> 提示 + 照样答对\", \"1\\n10001\\n\",\n         \"%d\\n\" % order_by_phi(10001), False, \"exceeds the stated range\"),\n\n        (\"m=1000001 超上限 -> 拒绝\", \"1\\n1000001\\n\", \"\", False, \"too large to compute\"),\n        (\"m 与 10 不互质 -> 中止\", \"1\\n2\\n\", \"\", False, \"not coprime\"),\n        (\"m=5 -> 中止\", \"1\\n5\\n\", \"\", False, \"not coprime\"),\n        (\"m=0 -> 中止\", \"1\\n0\\n\", \"\", False, \"must be > 0\"),\n        (\"m 为负 -> 中止\", \"1\\n-7\\n\", \"\", False, \"must be > 0\"),\n\n        (\"T 后缺 m -> 中止且 stdout 为空\", \"3\\n3\\n1111\\n\", \"\", False,\n         \"EOF while reading m\"),\n        (\"T 为负 -> 中止\", \"-1\\n\", \"\", False, \"negative case count\"),\n        (\"非整数 token -> 中止且 stdout 为空\", \"2\\n3\\nx\\n\", \"\", False,\n         \"invalid integer token\"),\n        (\"空输入 -> 无输出\", \"\", \"\", True, None),\n    ]\n\ndef _decode(raw):\n    for enc in (\"utf-8\", \"gbk\", \"latin-1\"):\n        try:\n            return raw.decode(enc)\n        except (UnicodeDecodeError, LookupError):\n            continue\n    return raw.decode(\"utf-8\", \"replace\")\n\ndef run(cmd, text, close_stdin=True, timeout=None):\n    p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n                         stderr=subprocess.PIPE)\n    if close_stdin:\n        out, err = p.communicate(text.encode(\"utf-8\"), timeout=timeout)\n        return out, err, p.returncode\n    p.stdin.write(text.encode(\"utf-8\"))\n    p.stdin.flush()\n    try:\n        rc = p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        return None, None, \"TIMEOUT\"\n    out = p.stdout.read()\n    err = p.stderr.read()\n    return out, err, rc\n\ndef check_subprocess(failures):\n    passed = 0\n    for (why, text, want_out, want_empty_err, must_contain) in subprocess_cases():\n        out, err, rc = run([sys.executable, SUBMISSION], text)\n        got = _decode(out).replace(\"\\r\\n\", \"\\n\")\n        got_err = _decode(err)\n        if got != want_out:\n            failures.append((\"端到端 \" + why, \"stdout=%r want %r\" % (got, want_out)))\n        elif want_empty_err and got_err != \"\":\n            failures.append((\"端到端 \" + why, \"stderr 应为空，实为 %r\" % (got_err,)))\n        elif (not want_empty_err) and (\"[!]\" not in got_err):\n            failures.append((\"端到端 \" + why, \"stderr 缺少 [!]：%r\" % (got_err,)))\n        elif must_contain and (must_contain not in got_err):\n            failures.append((\"端到端 \" + why,\n                             \"stderr 没点出真正的原因（缺 %r）：%r\"\n                             % (must_contain, got_err)))\n        else:\n            passed += 1\n    return passed\n\ndef check_detailed_run(failures):\n    cases = [(\"题面样例\", \"3\\n3\\n1111\\n2023\\n\"), (\"最坏一组 m=9981\", \"1\\n9981\\n\")]\n    passed = 0\n    for why, text in cases:\n        env = dict(os.environ)\n        env[\"PYTHONIOENCODING\"] = \"gbk\"\n        p = subprocess.run([sys.executable, os.path.join(HERE, \"repunit_detailed.py\")],\n                           input=text.encode(\"utf-8\"), stdout=subprocess.PIPE,\n                           stderr=subprocess.PIPE, env=env)\n        out = _decode(p.stdout)\n        err = _decode(p.stderr)\n        if p.returncode != 0:\n            failures.append((\"详细版子进程 \" + why,\n                             \"退出码 %d（应 0）：%s\" % (p.returncode,\n                                                       (err or out).strip()[-120:])))\n        elif \"Traceback\" in out or \"Traceback\" in err:\n            failures.append((\"详细版子进程 \" + why, \"输出里有 Traceback\"))\n        elif (\"Sum check\" not in out) or (\"ALL OK\" not in out):\n            failures.append((\"详细版子进程 \" + why, \"缺少 Sum check / ALL OK\"))\n        elif err.strip() != \"\":\n            failures.append((\"详细版子进程 \" + why, \"stderr 应为空，实为 %r\" % (err[:60],)))\n        else:\n            passed += 1\n    return passed\n\ndef check_reader_perf(failures):\n    class _FakeIn(object):\n\n        def __init__(self, line):\n            self._lines = [line, \"\"]\n            self._k = 0\n\n        def readline(self):\n            v = self._lines[self._k]\n            if self._k < len(self._lines) - 1:\n                self._k += 1\n            return v\n\n        def read(self):\n            rest = \"\".join(self._lines[self._k:])\n            self._k = len(self._lines) - 1\n            return rest\n\n        def isatty(self):\n            return False\n\n    def read_k(ntok, reps=5):\n        giant = \" \".join([\"7\"] * ntok) + \"\\n\"\n        best = None\n        old = sys.stdin\n        try:\n            for _ in range(reps):\n                sys.stdin = _FakeIn(giant)\n                nxt, _unused = mini.make_reader()\n                t0 = time.perf_counter()\n                got = 0\n                while nxt() is not None:\n                    got += 1\n                dt = time.perf_counter() - t0\n                if got != ntok:\n                    return None\n                if best is None or dt < best:\n                    best = dt\n        finally:\n            sys.stdin = old\n        return best\n\n    K = 20001\n    t1 = read_k(K)\n    t4 = read_k(4 * K)\n    if t1 is None or t4 is None:\n        failures.append((\"读取器压测\", \"读到的 token 数不对\"))\n        return None\n    ratio = t4 / max(t1, 1e-6)\n    if ratio >= 7.0:\n        failures.append((\"读取器斜率异常 t(4K)/t(K)=%.2f（线性应约 4）\" % ratio,\n                         \"疑似 buf.pop(0) 的 O(k^2)（陷阱 25）；\"\n                         \"t(K)=%.5fs t(4K)=%.5fs\" % (t1, t4)))\n    return ratio\n\ndef check_no_block(failures):\n    text = \"3\\n3\\n1111\\n2023\\n\"\n    t0 = time.time()\n    out, err, rc = run([sys.executable, SUBMISSION], text, close_stdin=False,\n                       timeout=8.0)\n    dt = time.time() - t0\n    if rc == \"TIMEOUT\":\n        failures.append((\"终端不阻塞\",\n                         \"喂完 %d 组后 8 秒仍未退出 —— 收尾又去 readline 了\" % 3))\n        return False\n    got = _decode(out).replace(\"\\r\\n\", \"\\n\")\n    if got != \"3\\n4\\n816\\n\":\n        failures.append((\"终端不阻塞\", \"stdout=%r\" % (got,)))\n        return False\n    return \"%.2f 秒\" % dt\n\ndef check_ast(failures):\n    import ast\n    bad_all = []\n    for p in (\"repunit.py\", \"repunit_detailed.py\"):\n        path = os.path.join(HERE, p)\n        src = open(path, encoding=\"utf-8\").read()\n\n        if src[:1] == \"\\ufeff\":\n            bad_all.append((p, \"带 UTF-8 BOM\"))\n\n        try:\n            src.encode(\"gbk\")\n        except UnicodeEncodeError as exc:\n            bad_ch = src[exc.start:exc.end]\n            bad_line = src[:exc.start].count(\"\\n\") + 1\n            bad_all.append((p, \"非 GBK 字符 %r @行 %d（GBK 下 print 会崩）\"\n                            % (bad_ch, bad_line)))\n        try:\n            tree = ast.parse(src, path)\n        except SyntaxError as exc:\n\n            bad_all.append((p, \"语法错误: %s @行 %s\" % (exc.msg, exc.lineno)))\n            continue\n        for node in ast.walk(tree):\n            if isinstance(node, ast.JoinedStr):\n                bad_all.append((p, \"f-string @%d\" % node.lineno))\n            if isinstance(node, ast.Nonlocal):\n                bad_all.append((p, \"nonlocal @%d\" % node.lineno))\n            if isinstance(node, ast.NamedExpr):\n                bad_all.append((p, \"walrus @%d\" % node.lineno))\n            if isinstance(node, ast.AnnAssign):\n                bad_all.append((p, \"annotation @%d\" % node.lineno))\n            if isinstance(node, ast.FunctionDef) and node.returns is not None:\n                bad_all.append((p, \"return annotation @%d\" % node.lineno))\n            if isinstance(node, ast.arg) and node.annotation is not None:\n                bad_all.append((p, \"arg annotation @%d\" % node.lineno))\n            if isinstance(node, ast.Call):\n                f = node.func\n                nm = f.attr if isinstance(f, ast.Attribute) else (\n                    f.id if isinstance(f, ast.Name) else \"\")\n                if nm in (\"read\", \"isatty\", \"input\"):\n                    bad_all.append((p, nm + \"() @%d\" % node.lineno))\n                if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                    bad_all.append((p, \"sys.stdin.buffer @%d\" % node.lineno))\n    for (p, why) in bad_all:\n        failures.append((\"AST \" + p, why))\n    return len(bad_all) == 0\n\ndef main():\n    failures = []\n\n    for (m, want, why) in ANCHORS:\n        got = solve(m)\n        if got != want:\n            failures.append((\"锚定 m=%d %s\" % (m, why), \"got %s want %d\" % (got, want)))\n\n        if order_by_phi(m) != want:\n            failures.append((\"锚定 m=%d 的期望值本身站不住\" % m,\n                             \"ord_{9m}(10)=%d != %d\" % (order_by_phi(m), want)))\n        if m <= 300 and brute_true(m, 9 * m + 2) != want:\n            failures.append((\"锚定 m=%d 与真大整数不符\" % m,\n                             \"brute=%s want=%d\" % (brute_true(m, 9 * m + 2), want)))\n\n    exh = 0\n    for m in range(1, 301):\n        if gcd_ref(m, 10) != 1:\n            continue\n        want = brute_true(m, 9 * m + 2)\n        got = solve(m)\n        exh += 1\n        if got != want:\n            failures.append((\"穷举 m=%d\" % m, \"mini=%s brute=%s\" % (got, want)))\n\n    full = 0\n    for m in range(1, 10000):\n        if gcd_ref(m, 10) != 1:\n            continue\n        got = solve(m)\n        want = order_by_phi(m)\n        full += 1\n        if got != want:\n            failures.append((\"全范围 m=%d\" % m, \"mini=%s ord=%s\" % (got, want)))\n            continue\n        if not is_minimal_order(m, got):\n            failures.append((\"最小性 m=%d\" % m, \"n=%s 不是 10 在模 9m 下的阶\" % (got,)))\n\n    det = 0\n    probe = [1, 3, 7, 9, 11, 37, 101, 1111, 2023, 4999, 9981, 10001]\n    for m in probe:\n        n_mini = solve(m)\n        n_det, chain = detailed.horner_steps(m)\n        n_ord = detailed.order_of_ten(m)\n        det += 1\n\n        if n_mini is None:\n            failures.append((\"详细版对照 m=%d\" % m, \"提交版返回 None（算不出解）\"))\n            continue\n        if n_det != n_mini:\n            failures.append((\"详细版秦九韶 m=%d\" % m, \"%s != %s\" % (n_det, n_mini)))\n        if n_ord != n_mini:\n            failures.append((\"详细版阶 m=%d\" % m, \"%s != %s\" % (n_ord, n_mini)))\n        if len(chain) != n_det or chain[-1] != 0:\n            failures.append((\"详细版余数链 m=%d\" % m,\n                             \"长度 %d，末项 %s\" % (len(chain), chain[-1] if chain else None)))\n        if 0 in chain[:-1]:\n            failures.append((\"详细版余数链 m=%d\" % m, \"前面就出现过 0（不是最小解）\"))\n\n        first_mod, big_mod = detailed.first_hit_by_bigint(m, n_mini)\n        if first_mod != n_mini:\n            failures.append((\"详细版 helper 最小性 m=%d\" % m,\n                             \"返回 %s，应为 %d\" % (first_mod, n_mini)))\n        v_indep = 0\n        for _ in range(n_mini):\n            v_indep = v_indep * 10 + 1\n        if big_mod != v_indep:\n            failures.append((\"详细版 helper 构造的数 m=%d\" % m,\n                             \"与独立逐位构造不一致（%s 位）\" % n_mini))\n        elif big_mod % m != 0:\n            failures.append((\"详细版 helper 整除 m=%d\" % m, \"A_n %% m = %d\" % (big_mod % m)))\n\n        v = 0\n        first_hit = None\n        for k in range(1, n_mini + 1):\n            v = v * 10 + 1\n            if first_hit is None and v % m == 0:\n                first_hit = k\n        if v % m != 0:\n            failures.append((\"真大整数 m=%d\" % m, \"A_n %% m = %d\" % (v % m)))\n        if first_hit != n_mini:\n            failures.append((\"全局最小性 m=%d\" % m,\n                             \"第一个能整除的是 %s，而答案是 %d\" % (first_hit, n_mini)))\n\n    sub_passed = check_subprocess(failures)\n\n    nb = check_no_block(failures)\n\n    ast_ok = check_ast(failures)\n\n    t0 = time.time()\n    out, err, rc = run([sys.executable, SUBMISSION],\n                       \"19\\n\" + \"\".join(\"%d\\n\" % x for x in (9981, 9973, 9967)))\n    dt = time.time() - t0\n    if dt > 5.0:\n        failures.append((\"最坏规模耗时\", \"%.2f 秒 > 5 秒\" % dt))\n\n    ratio = check_reader_perf(failures)\n\n    det_runs = check_detailed_run(failures)\n\n    if failures:\n        print(\"FAIL: %d failures\" % len(failures))\n        for what, why in failures[:5]:\n            print(\"  %s  ->  %s\" % (what, why))\n        return 1\n\n    print(\"OK: mini==brute(bigint) %d exhaustive | mini==ord %d full | order minimal | \"\n          \"detailed==mini==bigint %d probes | detailed-run %d/%d | anchors %d | \"\n          \"subprocess %d/%d | no-block %s | GBK+AST %s | worst-case %.2fs | \"\n          \"reader slope %.2f (lin~4)\"\n          % (exh, full, det, det_runs, 2, len(ANCHORS),\n             sub_passed, len(subprocess_cases()),\n             nb if nb else \"FAIL\", \"clean\" if ast_ok else \"VIOLATION\",\n             dt, ratio if ratio is not None else -1))\n    return 0\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n", "original": "#!/usr/bin/env python3\n\"\"\"\nVerification script for \"n 个 1\"（求最小 n 使 11...1 被 m 整除）.\n\n七类检查，全部通过才打印 OK：\n\n  0. 锚定用例        —— 专钉典型错法（尤其\"模 m 而不是模 9m\"：m=3 会答 1、正解 3）\n  1. 穷举真值对拍    —— m ≤ 300 且与 10 互质，用**真大整数**逐位构造 11...1 求最小 n\n  2. 全范围独立算法  —— m < 10000 全部，与「乘法阶 ord_{9m}(10)」对照（完全不同思路）\n  3. 最小性          —— 对每个 m 验证 10^n ≡ 1 (mod 9m) 且 n 的每个真因子幂都不行\n  4. 详细版三路一致  —— 提交版 / 详细版秦九韶 / 详细版阶 / 真大整数，四者不许分歧\n  5. OJ 端到端       —— 真起子进程跑 repunit.py，逐字节比对 stdout；错误场景 stdout 必须为空\n  6. 终端不阻塞      —— 喂完 T 组**不关闭 stdin**：必须立刻自行退出（不许再 readline 等数据）\n  7. AST 语法检查    —— 精确匹配调用名（不能用 grep：readline 含 read 子串会误报）\n\n被测对象是**真正提交的文件** repunit.py / repunit_detailed.py，不是内部副本。\n\n【注意】 本脚本刻意**不构造 int(\"1\" * n)**：Python 3.11+ 默认禁止 int<->str 转换超过 4300 位，\n   而本题 n 可达 9972。真大整数一律用「逐位累乘 v = v*10+1」构造。\n\nPass: prints \"OK: ...\" and exits 0.\nFail: prints first 5 failures and exits 1.\n\"\"\"\nimport importlib.util\nimport os\nimport subprocess\nimport sys\nimport time\n\nsys.dont_write_bytecode = True\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSUBMISSION = os.path.join(HERE, \"repunit.py\")\n\n\ndef _load(fname, modname):\n    \"\"\"载入待测文件本体（不是副本）。\"\"\"\n    spec = importlib.util.spec_from_file_location(modname, os.path.join(HERE, fname))\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\nmini = _load(\"repunit.py\", \"repunit_under_test\")\ndetailed = _load(\"repunit_detailed.py\", \"repunit_detailed_under_test\")\n\nsolve = mini.min_ones\ngcd_own = mini.gcd\n\n# ---------- 独立实现（测试脚本自己的，不借被测代码） ----------\nREP_CACHE = [0]                     # REP_CACHE[n] = 真大整数 11...1（n 个 1）\n\n\ndef rep(n):\n    \"\"\"真大整数：11...1（n 个 1），逐位累乘，缓存给穷举阶段用（n 很小）。\"\"\"\n    while len(REP_CACHE) <= n:\n        REP_CACHE.append(REP_CACHE[-1] * 10 + 1)\n    return REP_CACHE[n]\n\n\ndef rep_direct(n):\n    \"\"\"同上但不进缓存 —— 给 n 上千位的大用例用（避免缓存吃掉几十 MB）。\"\"\"\n    v = 0\n    for _ in range(n):\n        v = v * 10 + 1\n    return v\n\n\ndef brute_true(m, limit):\n    \"\"\"真值：真算 11...1，返回第一个能被 m 整除的 n（超限 None）。\"\"\"\n    for n in range(1, limit + 1):\n        if rep(n) % m == 0:\n            return n\n    return None\n\n\ndef gcd_ref(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\n\ndef factorize(x):\n    f = {}\n    d = 2\n    while d * d <= x:\n        while x % d == 0:\n            f[d] = f.get(d, 0) + 1\n            x //= d\n        d += 1\n    if x > 1:\n        f[x] = f.get(x, 0) + 1\n    return f\n\n\ndef order_by_phi(m):\n    \"\"\"独立算法：n = ord_{9m}(10)。取 φ(9m)，再用其质因子逐个往下除。\"\"\"\n    mod = 9 * m\n    phi = mod\n    for p in factorize(mod):\n        phi = phi // p * (p - 1)\n    n = phi\n    for p in factorize(phi):\n        while n % p == 0 and pow(10, n // p, mod) == 1:\n            n //= p\n    return n\n\n\ndef is_minimal_order(m, n):\n    \"\"\"验证 n 真是 10 在模 9m 下的**阶**（即最小性）：10^n ≡ 1 且每个真因子幂都不行。\"\"\"\n    mod = 9 * m\n    if pow(10, n, mod) != 1:\n        return False\n    for p in factorize(n):\n        if pow(10, n // p, mod) == 1:\n            return False\n    return True\n\n\n# ---------- 锚定用例（期望值都由真大整数/阶算法核对过，不手算） ----------\nANCHORS = [\n    (3, 3, \"★ 模 m 的错法会答 1：A_1=1 不被 3 整除，A_3=111=3×37\"),\n    (9, 9, \"★ 同上：A_9=111111111 是 9 的倍数，最小的就是这个 n=9\"),\n    (1111, 4, \"题面样例：1111 = 1111×1\"),\n    (2023, 816, \"题面样例：n=816\"),\n    (1, 1, \"m=1：1 能被 1 整除\"),\n    (11, 2, \"A_2 = 11\"),\n    (7, 6, \"A_6 = 111111 = 7×15873\"),\n    (13, 6, \"A_6 = 111111 = 13×8547\"),\n    (37, 3, \"A_3 = 111 = 37×3\"),\n    (41, 5, \"A_5 = 11111 = 41×271\"),\n    (101, 4, \"A_4 = 1111 = 101×11\"),\n    (9981, 9972, \"题面范围内实测最坏：n=9972（循环上界的依据）\"),\n]\n\n\nWORST19 = (9981, 9973, 9967, 9963, 9949, 9941, 9937, 9931, 9929, 9923, 9919,\n           9901, 9887, 9879, 9877, 9871, 9863, 9859, 9857)\n\n\ndef subprocess_cases():\n    \"\"\"(说明, 输入, 期望 stdout, stderr 是否必须为空, stderr 必须包含的子串)\n\n    最后一列专治\"诊断被改错也测不出来\"：错误场景下光看 \"有没有 [!]\" 分不出\n    到底是哪条守卫在报，所以**把诊断内容也钉住**（变异测试会用到）。\n    \"\"\"\n    sample = \"3\\n3\\n1111\\n2023\\n\"\n    return [\n        (\"题面样例\", sample, \"3\\n4\\n816\\n\", True, None),\n        (\"CRLF\", sample.replace(\"\\n\", \"\\r\\n\"), \"3\\n4\\n816\\n\", True, None),\n        (\"数同行 + 多空行\", \"\\n2 3 1111\\n\\n\", \"3\\n4\\n\", True, None),\n        (\"末尾无换行\", \"3\\n3\\n1111\\n2023\", \"3\\n4\\n816\\n\", True, None),\n        (\"T=0 -> 无输出\", \"0\\n\", \"\", True, None),\n        (\"单组 m=1\", \"1\\n1\\n\", \"1\\n\", True, None),\n        (\"最坏一组 m=9981\", \"1\\n9981\\n\", \"9972\\n\", True, None),\n        # 【注意】 19 组的期望值**现场算**（用已独立验证的 order_by_phi），不手抄 ——\n        #    上一版我是从一段被截断的输出里抄的，抄错了 4 个数（典型的陷阱 19）。\n        (\"19 组最坏\", \"19\\n\" + \"\".join(\"%d\\n\" % x for x in WORST19),\n         \"\".join(\"%d\\n\" % order_by_phi(x) for x in WORST19), True, None),\n        (\"同行多余数据 -> 提示但不影响 stdout\", \"2 3 1111 9999\\n\", \"3\\n4\\n\", False,\n         \"extra token\"),\n        # 题面范围外（m≥10000）：提示但照样算对，不丢答案。\n        # 期望值现场用 order_by_phi 算（与阶段 2 的独立算法同源）。\n        (\"m=10001 超范围 -> 提示 + 照样答对\", \"1\\n10001\\n\",\n         \"%d\\n\" % order_by_phi(10001), False, \"exceeds the stated range\"),\n        # m 的\"太大就不算\"上界（10^6）也要有用例，否则那条守卫不受任何断言保护\n        (\"m=1000001 超上限 -> 拒绝\", \"1\\n1000001\\n\", \"\", False, \"too large to compute\"),\n        (\"m 与 10 不互质 -> 中止\", \"1\\n2\\n\", \"\", False, \"not coprime\"),\n        (\"m=5 -> 中止\", \"1\\n5\\n\", \"\", False, \"not coprime\"),\n        (\"m=0 -> 中止\", \"1\\n0\\n\", \"\", False, \"must be > 0\"),\n        (\"m 为负 -> 中止\", \"1\\n-7\\n\", \"\", False, \"must be > 0\"),\n        # 本题是\"攒完一起输出\"：遇到坏数据就 return，**stdout 一个字节都没写过** ——\n        # 所以这里期望的是**空**，而不是\"已算出的那几行\"。\n        # （这是\"一起输入、一起输出\"顺带买到的性质：不会有半截输出。）\n        (\"T 后缺 m -> 中止且 stdout 为空\", \"3\\n3\\n1111\\n\", \"\", False,\n         \"EOF while reading m\"),\n        (\"T 为负 -> 中止\", \"-1\\n\", \"\", False, \"negative case count\"),\n        (\"非整数 token -> 中止且 stdout 为空\", \"2\\n3\\nx\\n\", \"\", False,\n         \"invalid integer token\"),\n        (\"空输入 -> 无输出\", \"\", \"\", True, None),\n    ]\n\n\ndef _decode(raw):\n    \"\"\"宽容解码（Windows 上 stderr 不是 tty 时按 GBK 落盘）。\"\"\"\n    for enc in (\"utf-8\", \"gbk\", \"latin-1\"):\n        try:\n            return raw.decode(enc)\n        except (UnicodeDecodeError, LookupError):\n            continue\n    return raw.decode(\"utf-8\", \"replace\")\n\n\ndef run(cmd, text, close_stdin=True, timeout=None):\n    \"\"\"起子进程跑一轮。close_stdin=False 时喂完数据**不关闭 stdin**（模拟终端）。\"\"\"\n    p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n                         stderr=subprocess.PIPE)\n    if close_stdin:\n        out, err = p.communicate(text.encode(\"utf-8\"), timeout=timeout)\n        return out, err, p.returncode\n    p.stdin.write(text.encode(\"utf-8\"))\n    p.stdin.flush()\n    try:\n        rc = p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        return None, None, \"TIMEOUT\"\n    out = p.stdout.read()\n    err = p.stderr.read()\n    return out, err, rc\n\n\ndef check_subprocess(failures):\n    \"\"\"阶段 5：端到端（stdout 逐字节、stderr 必须干净或点名诊断）。\"\"\"\n    passed = 0\n    for (why, text, want_out, want_empty_err, must_contain) in subprocess_cases():\n        out, err, rc = run([sys.executable, SUBMISSION], text)\n        got = _decode(out).replace(\"\\r\\n\", \"\\n\")\n        got_err = _decode(err)\n        if got != want_out:\n            failures.append((\"端到端 \" + why, \"stdout=%r want %r\" % (got, want_out)))\n        elif want_empty_err and got_err != \"\":\n            failures.append((\"端到端 \" + why, \"stderr 应为空，实为 %r\" % (got_err,)))\n        elif (not want_empty_err) and (\"[!]\" not in got_err):\n            failures.append((\"端到端 \" + why, \"stderr 缺少 [!]：%r\" % (got_err,)))\n        elif must_contain and (must_contain not in got_err):\n            failures.append((\"端到端 \" + why,\n                             \"stderr 没点出真正的原因（缺 %r）：%r\"\n                             % (must_contain, got_err)))\n        else:\n            passed += 1\n    return passed\n\n\ndef check_detailed_run(failures):\n    \"\"\"阶段 10：详细版必须**真能当子进程跑通**（不是只 import 它的函数）。\n\n    【注意】这条是审计加的：原先验证脚本只 import 详细版、调它的函数，**从不跑它的 main()**，\n    所以\"详细版打一半崩了 / 根本没输出 / 退出码非 0\"在验证体系里完全看不见 ——\n    实测真漏过一次（打印一个 GBK 编不出的符号，在 GBK locale 下抛 UnicodeEncodeError，③ 之后全断，\n    而它正是\"三条独立路径互相对账\"这个设计的存在理由）。\n    这里故意把子进程的输出编码钉成 gbk（模拟本机重定向/管道），别再让它在 GBK 下裸奔。\n    \"\"\"\n    cases = [(\"题面样例\", \"3\\n3\\n1111\\n2023\\n\"), (\"最坏一组 m=9981\", \"1\\n9981\\n\")]\n    passed = 0\n    for why, text in cases:\n        env = dict(os.environ)\n        env[\"PYTHONIOENCODING\"] = \"gbk\"\n        p = subprocess.run([sys.executable, os.path.join(HERE, \"repunit_detailed.py\")],\n                           input=text.encode(\"utf-8\"), stdout=subprocess.PIPE,\n                           stderr=subprocess.PIPE, env=env)\n        out = _decode(p.stdout)\n        err = _decode(p.stderr)\n        if p.returncode != 0:\n            failures.append((\"详细版子进程 \" + why,\n                             \"退出码 %d（应 0）：%s\" % (p.returncode,\n                                                       (err or out).strip()[-120:])))\n        elif \"Traceback\" in out or \"Traceback\" in err:\n            failures.append((\"详细版子进程 \" + why, \"输出里有 Traceback\"))\n        elif (\"Sum check\" not in out) or (\"ALL OK\" not in out):\n            failures.append((\"详细版子进程 \" + why, \"缺少 Sum check / ALL OK\"))\n        elif err.strip() != \"\":\n            failures.append((\"详细版子进程 \" + why, \"stderr 应为空，实为 %r\" % (err[:60],)))\n        else:\n            passed += 1\n    return passed\n\n\ndef check_reader_perf(failures):\n    \"\"\"阶段 9：读取器复杂度（斜率法，机器无关）。\n\n    本题的真实输入极小（T<20、一组一个 token），`pop(0)` 的 O(k^2) 在端到端里\n    **根本看不出来** —— 这正是陷阱 25 说的\"结构盲区\"。所以直接对 make_reader 压测：\n    同一段代码读 K 个 token 与读 4K 个，线性应 ≈4、平方应 ≈16。\n    比值不随机器快慢变化（比绝对阈值可靠；绝对阈值有低尾漏报风险）。\n    \"\"\"\n    class _FakeIn(object):\n        \"\"\"假 stdin：一次给一整行 token，之后 EOF。\n\n        除了 readline() 还要提供 read()/isatty() —— 否则读取器一旦退回\n        sys.stdin.read()（铁律 1 的坑），这里会抛 AttributeError 把验证脚本自己搞崩，\n        而\"脚本崩了\"在变异测试里**不算断言抓到**（那类退化其实由\"终端不阻塞\"阶段负责抓）。\n        \"\"\"\n\n        def __init__(self, line):\n            self._lines = [line, \"\"]\n            self._k = 0\n\n        def readline(self):\n            v = self._lines[self._k]\n            if self._k < len(self._lines) - 1:\n                self._k += 1\n            return v\n\n        def read(self):\n            rest = \"\".join(self._lines[self._k:])\n            self._k = len(self._lines) - 1\n            return rest\n\n        def isatty(self):\n            return False\n\n    def read_k(ntok, reps=5):\n        giant = \" \".join([\"7\"] * ntok) + \"\\n\"\n        best = None\n        old = sys.stdin\n        try:\n            for _ in range(reps):\n                sys.stdin = _FakeIn(giant)\n                nxt, _unused = mini.make_reader()\n                t0 = time.perf_counter()\n                got = 0\n                while nxt() is not None:\n                    got += 1\n                dt = time.perf_counter() - t0\n                if got != ntok:\n                    return None\n                if best is None or dt < best:\n                    best = dt\n        finally:\n            sys.stdin = old\n        return best\n\n    K = 20001\n    t1 = read_k(K)\n    t4 = read_k(4 * K)\n    if t1 is None or t4 is None:\n        failures.append((\"读取器压测\", \"读到的 token 数不对\"))\n        return None\n    ratio = t4 / max(t1, 1e-6)\n    if ratio >= 7.0:\n        failures.append((\"读取器斜率异常 t(4K)/t(K)=%.2f（线性应约 4）\" % ratio,\n                         \"疑似 buf.pop(0) 的 O(k^2)（陷阱 25）；\"\n                         \"t(K)=%.5fs t(4K)=%.5fs\" % (t1, t4)))\n    return ratio\n\n\ndef check_no_block(failures):\n    \"\"\"阶段 6：喂完 T 组**不关 stdin**，进程必须自行退出（不许再读一行等数据）。\"\"\"\n    text = \"3\\n3\\n1111\\n2023\\n\"\n    t0 = time.time()\n    out, err, rc = run([sys.executable, SUBMISSION], text, close_stdin=False,\n                       timeout=8.0)\n    dt = time.time() - t0\n    if rc == \"TIMEOUT\":\n        failures.append((\"终端不阻塞\",\n                         \"喂完 %d 组后 8 秒仍未退出 —— 收尾又去 readline 了\" % 3))\n        return False\n    got = _decode(out).replace(\"\\r\\n\", \"\\n\")\n    if got != \"3\\n4\\n816\\n\":\n        failures.append((\"终端不阻塞\", \"stdout=%r\" % (got,)))\n        return False\n    return \"%.2f 秒\" % dt\n\n\ndef check_ast(failures):\n    \"\"\"阶段 7：AST 精确匹配禁用语法（不能用 grep —— readline 含 read 子串会误报）\n    + 文件级 GBK 可编码性检查。\"\"\"\n    import ast\n    bad_all = []\n    for p in (\"repunit.py\", \"repunit_detailed.py\"):\n        path = os.path.join(HERE, p)\n        src = open(path, encoding=\"utf-8\").read()\n        # 用转义写法比较 BOM。**别写字面 BOM**：一是不显眼，二是批量替换时容易被\n        # 顺手删成空串、使这行变成恒假的死断言（本轮真踩了）。\n        if src[:1] == \"\\ufeff\":\n            bad_all.append((p, \"带 UTF-8 BOM\"))\n        # 【注意】本机 locale 是 GBK：只要文件里有一个 GBK 编不出的字符（比如箭头类符号、上标 2、emoji），\n        # 一旦它出现在 print 里，重定向/管道下就抛 UnicodeEncodeError（陷阱 31）。\n        # 这里直接要求**整个 .py 文件**都能 GBK 编码 —— 比逐条挑打印语句省事，\n        # 也能挡住\"以后把注释里的怪字符搬进 print\"。\n        # 这条断言是审计加的：详细版曾因打印一个 GBK 编不出的符号，在重定向下把 ③ 之后整段打不出来。\n        try:\n            src.encode(\"gbk\")\n        except UnicodeEncodeError as exc:\n            bad_ch = src[exc.start:exc.end]\n            bad_line = src[:exc.start].count(\"\\n\") + 1\n            bad_all.append((p, \"非 GBK 字符 %r @行 %d（GBK 下 print 会崩）\"\n                            % (bad_ch, bad_line)))\n        try:\n            tree = ast.parse(src, path)\n        except SyntaxError as exc:\n            # 别让语法错误把验证脚本自己搞崩（那样变异测试只记\"可疑\"、不算断言抓到）。\n            bad_all.append((p, \"语法错误: %s @行 %s\" % (exc.msg, exc.lineno)))\n            continue\n        for node in ast.walk(tree):\n            if isinstance(node, ast.JoinedStr):\n                bad_all.append((p, \"f-string @%d\" % node.lineno))\n            if isinstance(node, ast.Nonlocal):\n                bad_all.append((p, \"nonlocal @%d\" % node.lineno))\n            if isinstance(node, ast.NamedExpr):\n                bad_all.append((p, \"walrus @%d\" % node.lineno))\n            if isinstance(node, ast.AnnAssign):\n                bad_all.append((p, \"annotation @%d\" % node.lineno))\n            if isinstance(node, ast.FunctionDef) and node.returns is not None:\n                bad_all.append((p, \"return annotation @%d\" % node.lineno))\n            if isinstance(node, ast.arg) and node.annotation is not None:\n                bad_all.append((p, \"arg annotation @%d\" % node.lineno))\n            if isinstance(node, ast.Call):\n                f = node.func\n                nm = f.attr if isinstance(f, ast.Attribute) else (\n                    f.id if isinstance(f, ast.Name) else \"\")\n                if nm in (\"read\", \"isatty\", \"input\"):\n                    bad_all.append((p, nm + \"() @%d\" % node.lineno))\n                if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                    bad_all.append((p, \"sys.stdin.buffer @%d\" % node.lineno))\n    for (p, why) in bad_all:\n        failures.append((\"AST \" + p, why))\n    return len(bad_all) == 0\n\n\ndef main():\n    failures = []\n\n    # ---- 阶段 0: 锚定用例（每条都用真大整数/阶算法复核一遍） ----\n    for (m, want, why) in ANCHORS:\n        got = solve(m)\n        if got != want:\n            failures.append((\"锚定 m=%d %s\" % (m, why), \"got %s want %d\" % (got, want)))\n        # 锚定的期望值本身也要有独立依据，不能是\"我手抄的\"\n        if order_by_phi(m) != want:\n            failures.append((\"锚定 m=%d 的期望值本身站不住\" % m,\n                             \"ord_{9m}(10)=%d != %d\" % (order_by_phi(m), want)))\n        if m <= 300 and brute_true(m, 9 * m + 2) != want:\n            failures.append((\"锚定 m=%d 与真大整数不符\" % m,\n                             \"brute=%s want=%d\" % (brute_true(m, 9 * m + 2), want)))\n\n    # ---- 阶段 1: 穷举真值对拍（真大整数，m ≤ 300 且与 10 互质）----\n    exh = 0\n    for m in range(1, 301):\n        if gcd_ref(m, 10) != 1:\n            continue\n        want = brute_true(m, 9 * m + 2)\n        got = solve(m)\n        exh += 1\n        if got != want:\n            failures.append((\"穷举 m=%d\" % m, \"mini=%s brute=%s\" % (got, want)))\n\n    # ---- 阶段 2+3: 全范围（m<10000 与 10 互质）与乘法阶对照 + 最小性 ----\n    full = 0\n    for m in range(1, 10000):\n        if gcd_ref(m, 10) != 1:\n            continue\n        got = solve(m)\n        want = order_by_phi(m)\n        full += 1\n        if got != want:\n            failures.append((\"全范围 m=%d\" % m, \"mini=%s ord=%s\" % (got, want)))\n            continue\n        if not is_minimal_order(m, got):\n            failures.append((\"最小性 m=%d\" % m, \"n=%s 不是 10 在模 9m 下的阶\" % (got,)))\n\n    # ---- 阶段 4: 详细版与提交版、真大整数不许分歧 ----\n    det = 0\n    probe = [1, 3, 7, 9, 11, 37, 101, 1111, 2023, 4999, 9981, 10001]\n    for m in probe:\n        n_mini = solve(m)\n        n_det, chain = detailed.horner_steps(m)\n        n_ord = detailed.order_of_ten(m)\n        det += 1\n        # 【注意】 先把 None 拦住：提交版要是算不出（例如循环上界被改小），\n        #    后面 repunit_bigint(None) 会直接抛 TypeError 把验证脚本搞崩 ——\n        #    而\"脚本崩了\"在变异测试里**不能算断言抓到**（那是伪阳性）。宁可先报 FAIL。\n        if n_mini is None:\n            failures.append((\"详细版对照 m=%d\" % m, \"提交版返回 None（算不出解）\"))\n            continue\n        if n_det != n_mini:\n            failures.append((\"详细版秦九韶 m=%d\" % m, \"%s != %s\" % (n_det, n_mini)))\n        if n_ord != n_mini:\n            failures.append((\"详细版阶 m=%d\" % m, \"%s != %s\" % (n_ord, n_mini)))\n        if len(chain) != n_det or chain[-1] != 0:\n            failures.append((\"详细版余数链 m=%d\" % m,\n                             \"长度 %d，末项 %s\" % (len(chain), chain[-1] if chain else None)))\n        if 0 in chain[:-1]:\n            failures.append((\"详细版余数链 m=%d\" % m, \"前面就出现过 0（不是最小解）\"))\n        # 直接点名验收详细版那个 helper：它自己会算 first_hit 和 n 位的 A_n，\n        # 光看它打印的\"OK\"是没用的（那是它自说自话）—— 必须外部独立核对。\n        first_mod, big_mod = detailed.first_hit_by_bigint(m, n_mini)\n        if first_mod != n_mini:\n            failures.append((\"详细版 helper 最小性 m=%d\" % m,\n                             \"返回 %s，应为 %d\" % (first_mod, n_mini)))\n        v_indep = 0\n        for _ in range(n_mini):\n            v_indep = v_indep * 10 + 1\n        if big_mod != v_indep:\n            failures.append((\"详细版 helper 构造的数 m=%d\" % m,\n                             \"与独立逐位构造不一致（%s 位）\" % n_mini))\n        elif big_mod % m != 0:\n            failures.append((\"详细版 helper 整除 m=%d\" % m, \"A_n %% m = %d\" % (big_mod % m)))\n        # 真大整数核对 + **全局**最小性 —— 逐位累乘，绝不 int(\"1\"*n)；\n        # 【注意】 不能只比 (v//10) % m：m=3、n=6 那种\"局部最小\"会漏（陷阱 20/26 同类）。\n        v = 0\n        first_hit = None\n        for k in range(1, n_mini + 1):\n            v = v * 10 + 1\n            if first_hit is None and v % m == 0:\n                first_hit = k\n        if v % m != 0:\n            failures.append((\"真大整数 m=%d\" % m, \"A_n %% m = %d\" % (v % m)))\n        if first_hit != n_mini:\n            failures.append((\"全局最小性 m=%d\" % m,\n                             \"第一个能整除的是 %s，而答案是 %d\" % (first_hit, n_mini)))\n\n    # ---- 阶段 5: 端到端 ----\n    sub_passed = check_subprocess(failures)\n\n    # ---- 阶段 6: 终端不阻塞 ----\n    nb = check_no_block(failures)\n\n    # ---- 阶段 7: AST ----\n    ast_ok = check_ast(failures)\n\n    # ---- 阶段 8: 最坏规模的耗时（走真 stdin，含解释器启动） ----\n    t0 = time.time()\n    out, err, rc = run([sys.executable, SUBMISSION],\n                       \"19\\n\" + \"\".join(\"%d\\n\" % x for x in (9981, 9973, 9967)))\n    dt = time.time() - t0\n    if dt > 5.0:\n        failures.append((\"最坏规模耗时\", \"%.2f 秒 > 5 秒\" % dt))\n\n    # ---- 阶段 9: 读取器复杂度（斜率法）----\n    ratio = check_reader_perf(failures)\n\n    # ---- 阶段 10: 详细版真跑子进程（GBK 重定向下也不许崩）----\n    det_runs = check_detailed_run(failures)\n\n    if failures:\n        print(\"FAIL: %d failures\" % len(failures))\n        for what, why in failures[:5]:\n            print(\"  %s  ->  %s\" % (what, why))\n        return 1\n\n    print(\"OK: mini==brute(bigint) %d exhaustive | mini==ord %d full | order minimal | \"\n          \"detailed==mini==bigint %d probes | detailed-run %d/%d | anchors %d | \"\n          \"subprocess %d/%d | no-block %s | GBK+AST %s | worst-case %.2fs | \"\n          \"reader slope %.2f (lin~4)\"\n          % (exh, full, det, det_runs, 2, len(ANCHORS),\n             sub_passed, len(subprocess_cases()),\n             nb if nb else \"FAIL\", \"clean\" if ast_ok else \"VIOLATION\",\n             dt, ratio if ratio is not None else -1))\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}, {"label": "验证脚本 verify_repunit_c_mirror.py", "file": "verify_repunit_c_mirror.py", "lang": "py", "stripped": "import importlib.util\nimport io\nimport os\nimport random\nimport re\nimport subprocess\nimport sys\n\nsys.dont_write_bytecode = True\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSUBMISSION = os.path.join(HERE, \"repunit.py\")\n\ndef _load(fname, modname):\n    spec = importlib.util.spec_from_file_location(modname, os.path.join(HERE, fname))\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\nmini = _load(\"repunit.py\", \"repunit_under_test\")\n\ndef c_gcd_int(a, b):\n    while b != 0:\n        t = a % b\n        a = b\n        b = t\n    return a\n\nclass CInput(object):\n\n    SPACE = b\" \\t\\n\\v\\f\\r\"\n    DIGIT = b\"0123456789\"\n\n    def __init__(self, text):\n        self.d = text.encode(\"utf-8\")\n        self.i = 0\n\n    def scanf_int(self):\n        d = self.d\n        n = len(d)\n        j = self.i\n        while j < n and d[j] in self.SPACE:\n            j += 1\n        k = j\n        if k < n and d[k] in b\"+-\":\n            k += 1\n        d0 = k\n        while k < n and d[k] in self.DIGIT:\n            k += 1\n        if k == d0:\n            return None, False\n        v = int(d[j:k].decode(\"ascii\"))\n        self.i = k\n        return v, True\n\ndef c_mirror(text):\n    out, err = [], []\n    cin = CInput(text)\n\n    t, ok = cin.scanf_int()\n    if not ok:\n        return out, err, 0\n\n    if t < 0:\n        err.append(\"[!] negative case count T=%d\" % t)\n        return out, err, 1\n\n    if t == 0:\n        return out, err, 0\n\n    if t > 1024:\n        err.append(\"[!] T=%d too large to buffer (limit 1024)\" % t)\n        return out, err, 1\n\n    ans = []\n\n    for case_i in range(1, t + 1):\n\n        m, ok = cin.scanf_int()\n        if not ok:\n            err.append(\"[!] EOF while reading m of case %d/%d\" % (case_i, t))\n            return out, err, 1\n\n        if m <= 0 or c_gcd_int(m, 10) != 1:\n            err.append(\"[!] invalid m=%d at case %d (need m>0, gcd(m,10)=1)\" % (m, case_i))\n            return out, err, 1\n\n        if m >= 10000:\n            err.append(\"[!] m=%d exceeds the stated range (m<10000); computing anyway\" % m)\n\n        if m > 1000000:\n            err.append(\"[!] m=%d is too large to compute (limit %d)\" % (m, 1000000))\n            return out, err, 1\n\n        r = 0\n        n = 0\n        while n < 9 * m + 2:\n            n += 1\n            r = (r * 10 + 1) % m\n            if r == 0:\n                break\n\n        if r != 0:\n            err.append(\"[!] no solution within 9m+2 steps for m=%d\" % m)\n            return out, err, 1\n\n        ans.append(n)\n\n    for v in ans:\n        out.append(str(v))\n\n    return out, err, 0\n\ndef run_python(text):\n\n    env = dict(os.environ)\n    env[\"PYTHONIOENCODING\"] = \"utf-8\"\n    p = subprocess.run([sys.executable, SUBMISSION], input=text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)\n    out = p.stdout.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    err = p.stderr.decode(\"utf-8\", \"replace\")\n    return [l for l in out.split(\"\\n\") if l != \"\"], (\"[!]\" in err), p.returncode, err\n\ndef to_text(tokens):\n    if not tokens:\n        return \"\"\n    return tokens[0] + \"\\n\" + \"\".join(t + \"\\n\" for t in tokens[1:])\n\nKNOWN_DIVERGENT = [\n    (\"1\\n2023abc\\n\", \"stdout\",\n     \"C 前缀解析读成 2023 并输出答案；Python 判非法 token 中止\"),\n    (\"1\\n1_0\\n\", \"stdout\",\n     \"Python 按 PEP 515 把 '1_0' 当 10（gcd≠1 -> 中止、不输出）；\"\n     \"真 C 只读到 1 -> m=1 -> 输出 1。与上面同族：Python 严格 token vs C 前缀解析\"),\n\n    (\"2 3 1111 9999\\n\", \"bang\",\n     \"Python 收尾查缓冲区会打 [!] extra token(s)；C 按设计不做多余数据检查（见 repunit.c 头注）\"),\n\n    (\"1\\n１１\\n\", \"stdout\",\n     \"Python 的 int() 认全角数字（'１１' -> 11）并算出答案；真 C 的 scanf 在 C locale 下\"\n     \"只认 ASCII 数字，读不到 -> 中止、不输出\"),\n]\n\ndef check_c_anchors():\n    src = io.open(os.path.join(HERE, \"repunit.c\"), encoding=\"utf-8\").read()\n    anchors = [\n        ('#define M_LIMIT 1000000', \"上界常量\"),\n        ('#define ANS_MAX 1024', \"答案缓冲上限\"),\n        ('t > ANS_MAX', \"缓冲越界守卫\"),\n        ('scanf(\"%d\", &t)', \"读 T\"),\n        ('scanf(\"%d\", &m)', \"读 m\"),\n        ('gcd_int(m, 10) != 1', \"互质守卫\"),\n        ('m > M_LIMIT', \"太大就不算的守卫\"),\n        ('9 * m + 2', \"循环上界\"),\n        ('(r * 10 + 1) % m', \"秦九韶递推\"),\n        ('ans[case_i - 1] = n', \"先攒答案（读完再一起输出）\"),\n        ('printf(\"%d\\\\n\", ans[i])', \"最后统一输出\"),\n        ('fflush(stdout)', \"输出后刷出\"),\n        ('return 1', \"有问题的退出码\"),\n    ]\n    missing = []\n    for text, why in anchors:\n        if text not in src:\n            missing.append(\"repunit.c 里找不到锚点 %r（%s）—— 转写可能已经过期\"\n                           % (text, why))\n\n    for name, hardcoded in ((\"M_LIMIT\", 1000000), (\"ANS_MAX\", 1024)):\n        mm = re.search(r\"#define\\s+\" + name + r\"\\s+(\\d+)\", src)\n        if not mm:\n            missing.append(\"repunit.c 里没有 #define \" + name)\n        elif int(mm.group(1)) != hardcoded:\n            missing.append(\"repunit.c 的 %s=%s，而转写里写死的是 %d（两者必须一致）\"\n                           % (name, mm.group(1), hardcoded))\n    return missing, len(anchors)\n\ndef main():\n    failures = []\n    total = 0\n\n    cases = []\n\n    cases.append([\"3\", \"3\", \"1111\", \"2023\"])\n    cases.append([\"1\", \"1\"])\n    cases.append([\"0\"])\n    cases.append([\"1\", \"2\"])\n    cases.append([\"1\", \"0\"])\n    cases.append([\"1\", \"-7\"])\n    cases.append([\"-1\"])\n    cases.append([\"3\", \"3\", \"1111\"])\n    cases.append([\"1\", \"10001\"])\n    cases.append([\"2\", \"7\", \"13\"])\n    cases.append([\"19\"] + [str(x) for x in (9981, 9973, 9967)])\n\n    rnd = random.Random(20260927)\n    pool = [m for m in range(1, 10000) if mini.gcd(m, 10) == 1]\n    for _ in range(500):\n        t = rnd.randint(0, 5)\n        ms = [rnd.choice(pool) for _ in range(t)]\n        cases.append([str(t)] + [str(x) for x in ms])\n\n    for tokens in cases:\n        total += 1\n        text = to_text(tokens)\n        c_out, c_err, c_ret = c_mirror(text)\n        p_out, p_has_bang, p_ret, p_err = run_python(text)\n\n        if c_out != p_out:\n            failures.append((\"stdout 不一致 tokens=%s\" % tokens,\n                             \"C=%s Python=%s\" % (c_out, p_out)))\n            continue\n\n        c_has_bang = any(\"[!]\" in e for e in c_err)\n        if c_has_bang != p_has_bang:\n            failures.append((\"是否报错不一致 tokens=%s\" % tokens,\n                             \"C=%s Python=%s\" % (c_has_bang, p_has_bang)))\n            continue\n\n        if (c_ret != 0) and not p_has_bang:\n            failures.append((\"C 报错但 Python 没报 tokens=%s\" % tokens,\n                             \"C ret=%d\" % c_ret))\n\n    div_checked = 0\n    for text, aspect, why in KNOWN_DIVERGENT:\n        div_checked += 1\n        c_out, c_err, c_ret = c_mirror(text)\n        p_out, p_has_bang, p_ret, p_err = run_python(text)\n        c_has_bang = any(\"[!]\" in e for e in c_err)\n        tag = repr(text)[:40]\n        if aspect == \"stdout\":\n            if c_out == p_out:\n                failures.append((\"已知差异(stdout)居然一致了（注释该更新）%s\" % tag, why))\n        elif aspect == \"bang\":\n            if c_has_bang == p_has_bang:\n                failures.append((\"已知差异([!])居然一致了（注释该更新）%s\" % tag, why))\n        else:\n            failures.append((\"KNOWN_DIVERGENT 的 aspect 写错了：%r\" % (aspect,), why))\n\n    anchors_bad, n_anchors = check_c_anchors()\n    for why in anchors_bad:\n        failures.append((\"C 锚点校验\", why))\n\n    if failures:\n        print(\"FAIL: %d failures\" % len(failures))\n        for what, why in failures[:5]:\n            print(\"  %s  ->  %s\" % (what, why))\n        return 1\n\n    print(\"OK: C 逐行转写 == repunit.py（对拍 %d 组：锚定/边界/随机 T 组）；\"\n          \"repunit.c 锚点 %d 条全在；已知差异 %d 条仍按预期不同\"\n          % (total, n_anchors, div_checked))\n    return 0\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n", "original": "#!/usr/bin/env python3\n\"\"\"\nC 版逻辑核对 for n 个 1 —— 本机没有 C 编译器，改用「逐行转写成 Python」对拍。\n\n用法： python verify_repunit_c_mirror.py\n\n思路（照本仓库 `最小差/verify_min_diff_c_mirror.py` 的做法）：\n  把 repunit.c 的 main() **一行一行照着语义转写**成 Python 函数 c_mirror()，\n  再拿它与真正提交的 repunit.py 跑同一批输入、逐字节比对 stdout/stderr/退出码。\n  这样至少能确认：C 的控制流、循环上界、取模式、输出格式与 Python 版**逻辑等价**。\n\n【注意】 这**不能**替代真编译：转写本身可能抄错，C 还可能有编译器才暴露的问题\n   （类型溢出、未初始化、scanf 的缓冲区行为）。交付时必须如实说明这一点。\n\n已知且**有意保留**的差异（C 的 scanf 是前缀式解析，Python 版按 token 严格校验）：\n  * 喂 \"2023abc\" 这种「前面是数字、后面带垃圾」的 token：\n    C 读成 2023 并算出答案，Python 版判为非法 token 而中止 —— stdout 不同。\n    题面数据不会长这样，所以不修（改了也没法编译验证，风险更大）。\n  这类差异在 KNOWN_DIVERGENT 里列明；除了它们，两边必须完全一致。\n\nPass: prints \"OK: ...\" and exits 0.\nFail: prints first 5 differences and exits 1.\n\"\"\"\nimport importlib.util\nimport io\nimport os\nimport random\nimport re\nimport subprocess\nimport sys\n\nsys.dont_write_bytecode = True\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSUBMISSION = os.path.join(HERE, \"repunit.py\")\n\n\ndef _load(fname, modname):\n    spec = importlib.util.spec_from_file_location(modname, os.path.join(HERE, fname))\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\nmini = _load(\"repunit.py\", \"repunit_under_test\")\n\n\n# ---------- repunit.c 的逐行转写 ----------\ndef c_gcd_int(a, b):\n    \"\"\"C: static int gcd_int(int a, int b) { while (b) { t = a % b; a = b; b = t; } return a; }\"\"\"\n    while b != 0:\n        t = a % b\n        a = b\n        b = t\n    return a\n\n\nclass CInput(object):\n    \"\"\"模拟 stdin 的**字节流** + `scanf(\"%d\")`。\n\n    C 的 scanf 是**前缀式**的：跳过空白、扫可选的符号、再扫连续数字，\n    读到第一个非数字就停 —— **只消费到数字末尾**，剩下的字符留在缓冲区。\n    所以 \"2023abc\" 会被读成 2023，而 \"abc\" 原封不动留在那儿让下一次 scanf 失败。\n\n    【注意】必须是**字节级**模型，不能用 Python 的 `str.isdigit()/isspace()` ——\n    那两个是 Unicode 感知的（认全角数字 １、阿拉伯-印度数字 ٣、全角空格、NBSP），\n    会**比真 C 更宽容**，结果恰恰在\"C 与 Python 真会分道扬镳\"的输入上把两边\n    都\"读成功\"、报成一致（审计实测：全角 11 / 阿拉伯 3 都这样）。\n    真 C 在 C locale 下只认 ASCII：空白 = space \\\\t \\\\n \\\\v \\\\f \\\\r，数字 = 0-9。\n    \"\"\"\n\n    SPACE = b\" \\t\\n\\v\\f\\r\"\n    DIGIT = b\"0123456789\"\n\n    def __init__(self, text):\n        self.d = text.encode(\"utf-8\")     # 真 C 读的是字节；非 ASCII 字符天然不匹配\n        self.i = 0\n\n    def scanf_int(self):\n        d = self.d\n        n = len(d)\n        j = self.i\n        while j < n and d[j] in self.SPACE:\n            j += 1\n        k = j\n        if k < n and d[k] in b\"+-\":\n            k += 1\n        d0 = k\n        while k < n and d[k] in self.DIGIT:\n            k += 1\n        if k == d0:                       # 一个数字都没读到：不消费输入，返回失败\n            return None, False\n        v = int(d[j:k].decode(\"ascii\"))\n        self.i = k                        # 只消费到数字末尾\n        return v, True\n\n\ndef c_mirror(text):\n    \"\"\"把 repunit.c 的 main() 按控制流转写一遍（输入用字符流模型，见 CInput）。\n\n    返回 (out, err, ret)：out 是 stdout 的行列表，err 是 stderr 行列表，ret 是退出码。\n    \"\"\"\n    out, err = [], []\n    cin = CInput(text)\n\n    # int main(void) { if (scanf(\"%d\", &t) != 1) return 0;\n    t, ok = cin.scanf_int()\n    if not ok:\n        return out, err, 0\n    # if (t < 0) { fprintf(stderr, ...); return 1; }\n    if t < 0:\n        err.append(\"[!] negative case count T=%d\" % t)\n        return out, err, 1\n    # if (t == 0) return 0;\n    if t == 0:\n        return out, err, 0\n    # if (t > ANS_MAX) { ... return 1; }\n    if t > 1024:\n        err.append(\"[!] T=%d too large to buffer (limit 1024)\" % t)\n        return out, err, 1\n\n    ans = []\n\n    for case_i in range(1, t + 1):\n        # if (scanf(\"%d\", &m) != 1) { fprintf(stderr, ...); return 1; }\n        m, ok = cin.scanf_int()\n        if not ok:\n            err.append(\"[!] EOF while reading m of case %d/%d\" % (case_i, t))\n            return out, err, 1\n        # if (m <= 0 || gcd_int(m, 10) != 1) { ... return 1; }\n        if m <= 0 or c_gcd_int(m, 10) != 1:\n            err.append(\"[!] invalid m=%d at case %d (need m>0, gcd(m,10)=1)\" % (m, case_i))\n            return out, err, 1\n        # if (m >= 10000) fprintf(stderr, ...);\n        if m >= 10000:\n            err.append(\"[!] m=%d exceeds the stated range (m<10000); computing anyway\" % m)\n        # if (m > M_LIMIT) { ... return 1; }\n        if m > 1000000:\n            err.append(\"[!] m=%d is too large to compute (limit %d)\" % (m, 1000000))\n            return out, err, 1\n        # r = 0; n = 0; while (n < 9*m+2) { n++; r = (r*10+1) % m; if (r==0) break; }\n        r = 0\n        n = 0\n        while n < 9 * m + 2:\n            n += 1\n            r = (r * 10 + 1) % m\n            if r == 0:\n                break\n        # if (r != 0) { ... return 1; }\n        if r != 0:\n            err.append(\"[!] no solution within 9m+2 steps for m=%d\" % m)\n            return out, err, 1\n        # ans[case_i - 1] = n;   —— 先攒着\n        ans.append(n)\n\n    # 全部读完再一起输出：for (i = 0; i < t; i++) printf(\"%d\\n\", ans[i]); fflush(stdout);\n    for v in ans:\n        out.append(str(v))\n\n    return out, err, 0\n\n\n# ---------- 与真身对拍 ----------\ndef run_python(text):\n    \"\"\"跑真正的 repunit.py，返回 (out_lines, err_has_bang, ret, stderr_text)。\"\"\"\n    # 【注意】必须把子进程的 stdio 编码钉成 utf-8：输入里有非 ASCII（比如全角数字那条差异）\n    # 时，我们喂的是 UTF-8 字节，而子进程默认按 locale(GBK) 解 stdin -> 读成乱码 ->\n    # 判非法 token 中止 -> 两边\"看起来一致\"，把真正的分歧掩盖掉（本轮实测踩到，\n    # 与陷阱 31 同族：凡涉及编码，别依赖 locale，显式钉住）。\n    env = dict(os.environ)\n    env[\"PYTHONIOENCODING\"] = \"utf-8\"\n    p = subprocess.run([sys.executable, SUBMISSION], input=text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)\n    out = p.stdout.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    err = p.stderr.decode(\"utf-8\", \"replace\")\n    return [l for l in out.split(\"\\n\") if l != \"\"], (\"[!]\" in err), p.returncode, err\n\n\ndef to_text(tokens):\n    \"\"\"把 token 列表拼成一份像样的输入（第 1 个 token 后换行，其余每行一个）。\"\"\"\n    if not tokens:\n        return \"\"\n    return tokens[0] + \"\\n\" + \"\".join(t + \"\\n\" for t in tokens[1:])\n\n\n# 有意保留的差异：每条要写清**差在哪一维**（stdout 还是 stderr 的 [!]），\n# 否则\"分歧\"就成了一句含糊的话 —— 而且容易漏登（审计指出过）。\n# 这里直接存**原始输入文本**（不是 token 列表）：因为有一条差别恰恰在\"写不写在同一行\"上，\n# 用 token 列表表达不出来。\nKNOWN_DIVERGENT = [\n    (\"1\\n2023abc\\n\", \"stdout\",\n     \"C 前缀解析读成 2023 并输出答案；Python 判非法 token 中止\"),\n    (\"1\\n1_0\\n\", \"stdout\",\n     \"Python 按 PEP 515 把 '1_0' 当 10（gcd≠1 -> 中止、不输出）；\"\n     \"真 C 只读到 1 -> m=1 -> 输出 1。与上面同族：Python 严格 token vs C 前缀解析\"),\n    # ⚠️ 必须是**同一行**：Python 收尾只看缓冲区，多出来的 token 换行写就看不出去了\n    #    （想知道就得再 readline，而那样终端里会卡住不退出）。\n    (\"2 3 1111 9999\\n\", \"bang\",\n     \"Python 收尾查缓冲区会打 [!] extra token(s)；C 按设计不做多余数据检查（见 repunit.c 头注）\"),\n    # 同一族的还有：阿拉伯-印度数字 '٣'、全角空格 U+3000、NBSP U+00A0 —— 都归这一类。\n    # （审计实测：转写若用 Python 的 str.isdigit()/isspace()，这几条会被\"读成功\"而误报一致。）\n    (\"1\\n１１\\n\", \"stdout\",\n     \"Python 的 int() 认全角数字（'１１' -> 11）并算出答案；真 C 的 scanf 在 C locale 下\"\n     \"只认 ASCII 数字，读不到 -> 中止、不输出\"),\n]\n\n\ndef check_c_anchors():\n    \"\"\"确认这份\"手抄的 C\"与被测的 repunit.c 仍然对得上 —— 从 C 源码里抠关键 token 逐个校验。\n\n    【注意】本脚本是把 C 逐行**抄**成 Python 再对拍的：如果不看原文，任何人改了\n    repunit.c（甚至改错），对拍照样 OK —— 这正是本仓库陷阱 10（验证脚本测副本）的新形态。\n    这里用\"锚点文本必须出现在 C 文件里\"给转写上个扣：文件一改，这里先报警。\n    \"\"\"\n    src = io.open(os.path.join(HERE, \"repunit.c\"), encoding=\"utf-8\").read()\n    anchors = [\n        ('#define M_LIMIT 1000000', \"上界常量\"),\n        ('#define ANS_MAX 1024', \"答案缓冲上限\"),\n        ('t > ANS_MAX', \"缓冲越界守卫\"),\n        ('scanf(\"%d\", &t)', \"读 T\"),\n        ('scanf(\"%d\", &m)', \"读 m\"),\n        ('gcd_int(m, 10) != 1', \"互质守卫\"),\n        ('m > M_LIMIT', \"太大就不算的守卫\"),\n        ('9 * m + 2', \"循环上界\"),\n        ('(r * 10 + 1) % m', \"秦九韶递推\"),\n        ('ans[case_i - 1] = n', \"先攒答案（读完再一起输出）\"),\n        ('printf(\"%d\\\\n\", ans[i])', \"最后统一输出\"),\n        ('fflush(stdout)', \"输出后刷出\"),\n        ('return 1', \"有问题的退出码\"),\n    ]\n    missing = []\n    for text, why in anchors:\n        if text not in src:\n            missing.append(\"repunit.c 里找不到锚点 %r（%s）—— 转写可能已经过期\"\n                           % (text, why))\n    # 常量的**具体数值**也要对得上：转写里这两个数是手写死的\n    for name, hardcoded in ((\"M_LIMIT\", 1000000), (\"ANS_MAX\", 1024)):\n        mm = re.search(r\"#define\\s+\" + name + r\"\\s+(\\d+)\", src)\n        if not mm:\n            missing.append(\"repunit.c 里没有 #define \" + name)\n        elif int(mm.group(1)) != hardcoded:\n            missing.append(\"repunit.c 的 %s=%s，而转写里写死的是 %d（两者必须一致）\"\n                           % (name, mm.group(1), hardcoded))\n    return missing, len(anchors)\n\n# 另有几类「行为一致、措辞不同」，**不算**分歧（stdout 都是空、都打了 [!]）：\n#   * [\"1x\", \"7\"]  —— C 卡在 'x' 上报 \"EOF while reading m\"；Python 报 \"invalid integer token\"\n#   * [\"1\", \"0\"]   —— 两边都拒绝 m=0，但一个说 \"must be > 0\"、一个是 Python 版自己的措辞\n# 对拍脚本只比 stdout + 是否报错，不比对 stderr 文案（C 与 Python 的文案本来就不同）。\n\n\ndef main():\n    failures = []\n    total = 0\n\n    cases = []\n\n    # 1) 锚定 + 题面样例\n    cases.append([\"3\", \"3\", \"1111\", \"2023\"])\n    cases.append([\"1\", \"1\"])\n    cases.append([\"0\"])\n    cases.append([\"1\", \"2\"])                 # gcd≠1\n    cases.append([\"1\", \"0\"])\n    cases.append([\"1\", \"-7\"])\n    cases.append([\"-1\"])\n    cases.append([\"3\", \"3\", \"1111\"])         # 读到一半没了\n    cases.append([\"1\", \"10001\"])             # 超范围但可算\n    cases.append([\"2\", \"7\", \"13\"])\n    cases.append([\"19\"] + [str(x) for x in (9981, 9973, 9967)])\n\n    # 2) 随机合法输入（T 组、m 与 10 互质、含 1 与 9981 等边角）\n    rnd = random.Random(20260927)\n    pool = [m for m in range(1, 10000) if mini.gcd(m, 10) == 1]\n    for _ in range(500):\n        t = rnd.randint(0, 5)\n        ms = [rnd.choice(pool) for _ in range(t)]\n        cases.append([str(t)] + [str(x) for x in ms])\n\n    for tokens in cases:\n        total += 1\n        text = to_text(tokens)\n        c_out, c_err, c_ret = c_mirror(text)\n        p_out, p_has_bang, p_ret, p_err = run_python(text)\n\n        if c_out != p_out:\n            failures.append((\"stdout 不一致 tokens=%s\" % tokens,\n                             \"C=%s Python=%s\" % (c_out, p_out)))\n            continue\n        # stderr：两边都\"有/无 [!]\"即可（措辞不同没关系，C 与 Python 的文案本来就不同）\n        c_has_bang = any(\"[!]\" in e for e in c_err)\n        if c_has_bang != p_has_bang:\n            failures.append((\"是否报错不一致 tokens=%s\" % tokens,\n                             \"C=%s Python=%s\" % (c_has_bang, p_has_bang)))\n            continue\n        # 退出码约定：C 是 0=正常结束 / 1=数据有问题；Python 恒 0\n        if (c_ret != 0) and not p_has_bang:\n            failures.append((\"C 报错但 Python 没报 tokens=%s\" % tokens,\n                             \"C ret=%d\" % c_ret))\n\n    # 3) 有意保留的差异：必须**在指定的那一维上确实不同**（否则说明注释过时了）\n    div_checked = 0\n    for text, aspect, why in KNOWN_DIVERGENT:\n        div_checked += 1\n        c_out, c_err, c_ret = c_mirror(text)\n        p_out, p_has_bang, p_ret, p_err = run_python(text)\n        c_has_bang = any(\"[!]\" in e for e in c_err)\n        tag = repr(text)[:40]\n        if aspect == \"stdout\":\n            if c_out == p_out:\n                failures.append((\"已知差异(stdout)居然一致了（注释该更新）%s\" % tag, why))\n        elif aspect == \"bang\":\n            if c_has_bang == p_has_bang:\n                failures.append((\"已知差异([!])居然一致了（注释该更新）%s\" % tag, why))\n        else:\n            failures.append((\"KNOWN_DIVERGENT 的 aspect 写错了：%r\" % (aspect,), why))\n\n    # 4) 转写与被测的 repunit.c 必须仍然对得上（别让它变成\"测自己的抄本\"）\n    anchors_bad, n_anchors = check_c_anchors()\n    for why in anchors_bad:\n        failures.append((\"C 锚点校验\", why))\n\n    if failures:\n        print(\"FAIL: %d failures\" % len(failures))\n        for what, why in failures[:5]:\n            print(\"  %s  ->  %s\" % (what, why))\n        return 1\n\n    print(\"OK: C 逐行转写 == repunit.py（对拍 %d 组：锚定/边界/随机 T 组）；\"\n          \"repunit.c 锚点 %d 条全在；已知差异 %d 条仍按预期不同\"\n          % (total, n_anchors, div_checked))\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}, {"label": "验证脚本 verify_repunit_mutations.py", "file": "verify_repunit_mutations.py", "lang": "py", "stripped": "import io\nimport os\nimport subprocess\nimport sys\n\nsys.dont_write_bytecode = True\n\ntry:\n    sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\nexcept Exception:\n    pass\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nPY_SRC = os.path.join(HERE, \"repunit.py\")\nDET_SRC = os.path.join(HERE, \"repunit_detailed.py\")\nPY_VERIFIER = os.path.join(HERE, \"verify_repunit.py\")\n\nPY_MUTATIONS = [\n    (\"P1: 读取器退回 pop(0)（O(k^2) 悬崖）\",\n     \"            buf.extend(reversed(line.split()))\\n        return buf.pop()\",\n     \"            buf.extend(line.split())\\n        return buf.pop(0)\"),\n\n    (\"P2: 秦九韶漏掉 +1（r = 10r % m）\",\n     \"        r = (r * 10 + 1) % m\",\n     \"        r = (r * 10) % m\"),\n\n    (\"P3: 起手 r=1（跳过第一位 -> n 差 1；m=3 会答 1）\",\n     \"    r = 0\\n    limit = 9 * m + 2\",\n     \"    r = 1\\n    limit = 9 * m + 2\"),\n\n    (\"P4: 循环上界砍成 2 步（大 n 的用例算不出来）\",\n     \"    limit = 9 * m + 2\",\n     \"    limit = 2\"),\n\n    (\"P5: gcd 守卫改成只拦负数（报错原因错、且能算就往下算）\",\n     \"        if gcd(m, 10) != 1:\",\n     \"        if m < 0:\"),\n\n    (\"P6: 输出多加一行 Case 前缀（格式错）\",\n     \"        sys.stdout.write(\\\"\\\\n\\\".join(out) + \\\"\\\\n\\\")\",\n     \"        sys.stdout.write(\\\"Case 1\\\\n\\\" + \\\"\\\\n\\\".join(out) + \\\"\\\\n\\\")\"),\n\n    (\"P7: 收尾多余数据检查关掉（静默吞掉多余 token）\",\n     \"    if has_buffered():\",\n     \"    if False and has_buffered():\"),\n\n    (\"P8: 收尾改成再读一行（终端里打完答案不退出）\",\n     \"    if has_buffered():\\n        print(\\\"[!] extra token(s) after \",\n     \"    if nxt() is not None:\\n        print(\\\"[!] extra token(s) after \"),\n\n    (\"P9: 超范围提示删掉（m≥10000 静默计算）\",\n     \"        if m >= 10000:                     # 题面范围外，但公式照样成立 -> 提示后继续算\",\n     \"        if False:\"),\n\n    (\"P11: 删掉 m>10^6 的「太大就不算」守卫（该守卫无断言保护）\",\n     \"        if m > 1000000:\",\n     \"        if False:\"),\n\n    (\"P12: 给提交版开头塞一个 UTF-8 BOM（老 OJ 会炸）\",\n     \"# -*- coding: utf-8 -*-\\n#\\n# n 个 1\",\n     \"\\ufeff# -*- coding: utf-8 -*-\\n#\\n# n 个 1\"),\n]\n\nDET_MUTATIONS = [\n    (\"D1: 详细版秦九韶模成 9m（与提交版分歧）\",\n     \"        r = (r * 10 + 1) % m\",\n     \"        r = (r * 10 + 1) % (9 * m)\"),\n\n    (\"D2: 详细版真大整数构造漏 +1（11...1 变成了 10...0）\",\n     \"        v = v * 10 + 1\",\n     \"        v = v * 10\"),\n\n    (\"D3: 详细版阶算法短路（直接返回 φ(9m)）\",\n     \"        while n % p == 0 and pow(10, n // p, mod) == 1:\",\n     \"        while False:\"),\n\n    (\"D4: 详细版余数链掺假（记的不是真余数）\",\n     \"        remainders.append(r)\",\n     \"        remainders.append(r * 0)\"),\n\n    (\"D5: 详细版把 '<=>' 换回非 GBK 的 '\\u27fa'（重定向/管道下 print 直接崩）\",\n     'print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m)\")',\n     'print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) \\u27fa 10^n ≡ 1 (mod 9m)\")'),\n\n    (\"D6: 详细版 main() 一开头就抛异常（原先验证脚本从不跑它的 main，看不见）\",\n     \"def main():\\n    nxt = make_reader()\",\n     \"def main():\\n    raise RuntimeError(\\\"boom\\\")\\n    nxt = make_reader()\"),\n]\n\nJS_MUTATIONS = [\n    (\"M1: 动画秦九韶漏掉 +1\",\n     \"    r = (r * 10 + 1) % m;\",\n     \"    r = (r * 10) % m;\"),\n\n    (\"M2: 动画起手 r=1（步数差 1）\",\n     \"  var r = 0;\",\n     \"  var r = 1;\"),\n\n    (\"M3: 动画余数记录错位（把每一步的 r 记成上一步的）\",\n     \"    rows.push({ n: n, r: r });\",\n     \"    rows.push({ n: n, r: prevR });\"),\n\n    (\"M4: 动画终态答案取最后一步的 n（不是首个 r==0 的 n）\",\n     \"  return { n: found, rows: rows, limit: limit };\",\n     \"  return { n: rows.length, rows: rows, limit: limit };\"),\n\n    (\"M5: 复用判据只剩「是否首次渲染」（换 m 后表格不重建、行数对不上）\",\n     \"  if (box._rows === undefined || box._m !== M || box._rows.length !== view.length) {\",\n     \"  if (box._rows === undefined) {\"),\n\n    (\"M6: 数字条不再高亮「刚添的那个 1」（图例承诺落空）\",\n     \"    if (st.cur.type === \\\"step\\\" && upto <= SHOW) {\\n      html[html.length - 1] = '<div class=\\\"digit new\\\">1</div>';\\n    }\",\n     \"\"),\n]\n\ndef run(cmd):\n    env = dict(os.environ)\n    env[\"PYTHONIOENCODING\"] = \"utf-8\"\n    p = subprocess.run(cmd, capture_output=True, text=True, encoding=\"utf-8\",\n                       errors=\"replace\", cwd=HERE, env=env)\n    out = (p.stdout or \"\") + (p.stderr or \"\")\n    marked = (\"FAIL\" in (p.stdout or \"\"))\n    crashed = (\"Traceback (most recent call last)\" in out)\n    return (p.returncode != 0 and marked and not crashed), p\n\ndef first_failure(out):\n    lines = (out or \"\").split(\"\\n\")\n    for line in lines:\n        if line.startswith(\"  \") and line.strip():\n            body = line.strip()\n            if body.startswith(\"FAIL\") or body.startswith(\"OK\"):\n                continue\n            return body[:95]\n    for line in lines:\n        if line.startswith(\"FAIL:\") or line.startswith(\"FAIL \"):\n            return line.strip()[:95]\n    return lines[0][:95] if lines else \"(无输出)\"\n\ndef write_exact(path, text):\n    io.open(path, \"w\", encoding=\"utf-8\", newline=\"\").write(text)\n\ndef mutate_and_check(src_path, mutations, cmd, label):\n    original = io.open(src_path, encoding=\"utf-8\", newline=\"\").read()\n    nl = \"\\r\\n\" if \"\\r\\n\" in original else \"\\n\"\n    caught = 0\n    missed = []\n    try:\n        for name, frm, to in mutations:\n            frm_x = frm.replace(\"\\n\", nl)\n            to_x = to.replace(\"\\n\", nl)\n            if frm_x not in original:\n                print(\"  [SKIP] \" + name + \" —— 找不到锚点文本（代码改过？）\")\n                missed.append(name + \"（锚点失效）\")\n                continue\n            write_exact(src_path, original.replace(frm_x, to_x, 1))\n            failed, p = run(cmd)\n            write_exact(src_path, original)\n            if failed:\n                caught += 1\n                print(\"  [抓到] \" + name + \"  ->  \" + first_failure(p.stdout))\n            elif p.returncode != 0:\n                missed.append(name + \"（验证脚本崩溃，非断言失败）\")\n                print(\"  [可疑] \" + name + \"  <- 返回码 != 0 但无 FAIL 标记：\"\n                      \"验证脚本像是崩了，不能算断言抓到\")\n            else:\n                missed.append(name)\n                print(\"  [漏了] \" + name + \"  <- 这条断言没牙齿，要补强\")\n    finally:\n        write_exact(src_path, original)\n\n    failed, p = run(cmd)\n    restored = not failed\n    print(\"  \" + label + \" 变异捕获率: \" + str(caught) + \"/\" + str(len(mutations))\n          + \"；还原后: \" + (\"仍全绿 OK\" if restored else \"竟然 FAIL（没还原干净！）\"))\n    return caught, len(mutations), restored, missed\n\ndef main():\n    print(\"提交版（repunit.py <- verify_repunit.py）\")\n    c1, n1, r1, miss1 = mutate_and_check(PY_SRC, PY_MUTATIONS,\n                                         [sys.executable, PY_VERIFIER], \"提交版\")\n    print(\"\")\n    print(\"详细版（repunit_detailed.py <- verify_repunit.py）\")\n    c2, n2, r2, miss2 = mutate_and_check(DET_SRC, DET_MUTATIONS,\n                                         [sys.executable, PY_VERIFIER], \"详细版\")\n\n    c3, n3, r3, miss3 = 0, 0, True, []\n    js_verifier = os.path.join(HERE, \"verify_repunit_animation.js\")\n    html_src = os.path.join(HERE, \"repunit_animation.html\")\n    if os.path.exists(js_verifier) and os.path.exists(html_src):\n        print(\"\")\n        print(\"动画侧（repunit_animation.html <- verify_repunit_animation.js）\")\n        c3, n3, r3, miss3 = mutate_and_check(html_src, JS_MUTATIONS,\n                                             [\"node\", js_verifier], \"动画\")\n    else:\n        print(\"\")\n        print(\"（动画脚本还没生成，跳过动画侧变异）\")\n\n    all_missed = miss1 + miss2 + miss3\n    print(\"\")\n    if all_missed:\n        print(\"FAIL: 漏掉的变异 \" + str(len(all_missed)) + \" 个 -> 这些断言是装饰品：\")\n        for m in all_missed:\n            print(\"  - \" + m)\n        return 1\n    print(\"OK: 变异捕获率 \" + str(c1 + c2 + c3) + \"/\" + str(n1 + n2 + n3)\n          + \"（提交版 \" + str(c1) + \"/\" + str(n1)\n          + \"，详细版 \" + str(c2) + \"/\" + str(n2)\n          + \"，动画 \" + str(c3) + \"/\" + str(n3)\n          + \"）；还原后验证脚本均仍全绿\")\n    return 0\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n", "original": "#!/usr/bin/env python3\n\"\"\"\n变异测试（mutation testing）for n 个 1 —— 给「断言本身」做体检。\n\n用法： python verify_repunit_mutations.py\n\n思路：把被测代码**故意改回错的**（每次一处），跑验证脚本，看它认不认。\n      - 认出来（验证脚本 FAIL） -> 该断言有牙齿\n      - 认不出来（仍然 OK）     -> 该断言是**装饰品**，等于没查\n\n为什么需要它（本仓库的真实教训）：\n  * 0/1 背包详细版曾有断言 `dp[i][j] != dp[i-1][j] => w <= j`，恒真、打不掉任何变异。\n  * 连通分支数的读取器 O(k^2)（陷阱 25）在**结构上看不见**：算法测试都直接调 solve()、\n    绕开了读取器。本题更极端 —— 真实输入只有 T<20 个 token，端到端**永远**显不出来，\n    必须单独对 make_reader 做斜率压测才抓得住（这就是 P1 变异的意义）。\n  * 错误场景只断言\"stdout 为空 + 有没有 [!]\"是不够的：守卫被改成\"报错但报错原因不对\"\n    照样能通过。所以本题把**诊断内容**也钉住了（P5 变异验证这一点）。\n\nPython 侧变异（repunit.py / repunit_detailed.py）：\n  P1 读取器退回 pop(0)（O(k^2)）        P2 秦九韶漏掉 +1\n  P3 起手 r=1（跳过第一位 -> n 差 1）  P4 循环上界砍成 2 步\n  P5 gcd 守卫改成只拦负数              P6 输出加 Case 前缀（格式错）\n  P7 收尾多余数据检查关掉              P8 收尾改成\"再读一行\"（终端阻塞）\n  P9 超范围提示删掉                    D1 详细版秦九韶模成 9m\n  D2 详细版真大整数构造漏 +1           D3 详细版阶算法短路\n  D4 详细版余数链掺假\n\nPass: 全部变异都被抓到，且还原后验证脚本仍全绿。\nFail: 打印漏掉的变异（= 需要补强断言）。\n\"\"\"\nimport io\nimport os\nimport subprocess\nimport sys\n\nsys.dont_write_bytecode = True\n\n# 【注意】本机 locale 是 GBK：验证脚本捕获到的失败信息里含中文，\n# 若子进程按 GBK 输出、这边按 UTF-8 解码，就会解出 U+FFFD，再 print 到 GBK 控制台直接崩\n# （陷阱 31 的又一变种 —— 实测崩溃点就在\"[抓到] ...\"这一行，必然发生在第一条变异上）。\n# 两手都要有：① 子进程一律 UTF-8 输出 ② 自己的 stdout 也改成 UTF-8。\ntry:\n    sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\nexcept Exception:\n    pass\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nPY_SRC = os.path.join(HERE, \"repunit.py\")\nDET_SRC = os.path.join(HERE, \"repunit_detailed.py\")\nPY_VERIFIER = os.path.join(HERE, \"verify_repunit.py\")\n\nPY_MUTATIONS = [\n    (\"P1: 读取器退回 pop(0)（O(k^2) 悬崖）\",\n     \"            buf.extend(reversed(line.split()))\\n        return buf.pop()\",\n     \"            buf.extend(line.split())\\n        return buf.pop(0)\"),\n\n    (\"P2: 秦九韶漏掉 +1（r = 10r % m）\",\n     \"        r = (r * 10 + 1) % m\",\n     \"        r = (r * 10) % m\"),\n\n    (\"P3: 起手 r=1（跳过第一位 -> n 差 1；m=3 会答 1）\",\n     \"    r = 0\\n    limit = 9 * m + 2\",\n     \"    r = 1\\n    limit = 9 * m + 2\"),\n\n    (\"P4: 循环上界砍成 2 步（大 n 的用例算不出来）\",\n     \"    limit = 9 * m + 2\",\n     \"    limit = 2\"),\n\n    (\"P5: gcd 守卫改成只拦负数（报错原因错、且能算就往下算）\",\n     \"        if gcd(m, 10) != 1:\",\n     \"        if m < 0:\"),\n\n    (\"P6: 输出多加一行 Case 前缀（格式错）\",\n     \"        sys.stdout.write(\\\"\\\\n\\\".join(out) + \\\"\\\\n\\\")\",\n     \"        sys.stdout.write(\\\"Case 1\\\\n\\\" + \\\"\\\\n\\\".join(out) + \\\"\\\\n\\\")\"),\n\n    (\"P7: 收尾多余数据检查关掉（静默吞掉多余 token）\",\n     \"    if has_buffered():\",\n     \"    if False and has_buffered():\"),\n\n    (\"P8: 收尾改成再读一行（终端里打完答案不退出）\",\n     \"    if has_buffered():\\n        print(\\\"[!] extra token(s) after \",\n     \"    if nxt() is not None:\\n        print(\\\"[!] extra token(s) after \"),\n\n    (\"P9: 超范围提示删掉（m≥10000 静默计算）\",\n     \"        if m >= 10000:                     # 题面范围外，但公式照样成立 -> 提示后继续算\",\n     \"        if False:\"),\n\n    (\"P11: 删掉 m>10^6 的「太大就不算」守卫（该守卫无断言保护）\",\n     \"        if m > 1000000:\",\n     \"        if False:\"),\n\n    (\"P12: 给提交版开头塞一个 UTF-8 BOM（老 OJ 会炸）\",\n     \"# -*- coding: utf-8 -*-\\n#\\n# n 个 1\",\n     \"\\ufeff# -*- coding: utf-8 -*-\\n#\\n# n 个 1\"),\n]\n\nDET_MUTATIONS = [\n    (\"D1: 详细版秦九韶模成 9m（与提交版分歧）\",\n     \"        r = (r * 10 + 1) % m\",\n     \"        r = (r * 10 + 1) % (9 * m)\"),\n\n    (\"D2: 详细版真大整数构造漏 +1（11...1 变成了 10...0）\",\n     \"        v = v * 10 + 1\",\n     \"        v = v * 10\"),\n\n    (\"D3: 详细版阶算法短路（直接返回 φ(9m)）\",\n     \"        while n % p == 0 and pow(10, n // p, mod) == 1:\",\n     \"        while False:\"),\n\n    (\"D4: 详细版余数链掺假（记的不是真余数）\",\n     \"        remainders.append(r)\",\n     \"        remainders.append(r * 0)\"),\n\n    # D5/D6 是审计加的：这两条**证明新增的两道防线真的会咬**\n    (\"D5: 详细版把 '<=>' 换回非 GBK 的 '\\u27fa'（重定向/管道下 print 直接崩）\",\n     'print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) <=> 10^n ≡ 1 (mod 9m)\")',\n     'print(\"  ③ 乘法阶核对（完全不同的思路）：A_n ≡ 0 (mod m) \\u27fa 10^n ≡ 1 (mod 9m)\")'),\n\n    (\"D6: 详细版 main() 一开头就抛异常（原先验证脚本从不跑它的 main，看不见）\",\n     \"def main():\\n    nxt = make_reader()\",\n     \"def main():\\n    raise RuntimeError(\\\"boom\\\")\\n    nxt = make_reader()\"),\n]\n\n# 动画侧变异（repunit_animation.html）—— 用 node 抽 <script> 实跑验收\nJS_MUTATIONS = [\n    (\"M1: 动画秦九韶漏掉 +1\",\n     \"    r = (r * 10 + 1) % m;\",\n     \"    r = (r * 10) % m;\"),\n\n    (\"M2: 动画起手 r=1（步数差 1）\",\n     \"  var r = 0;\",\n     \"  var r = 1;\"),\n\n    (\"M3: 动画余数记录错位（把每一步的 r 记成上一步的）\",\n     \"    rows.push({ n: n, r: r });\",\n     \"    rows.push({ n: n, r: prevR });\"),\n\n    (\"M4: 动画终态答案取最后一步的 n（不是首个 r==0 的 n）\",\n     \"  return { n: found, rows: rows, limit: limit };\",\n     \"  return { n: rows.length, rows: rows, limit: limit };\"),\n\n    (\"M5: 复用判据只剩「是否首次渲染」（换 m 后表格不重建、行数对不上）\",\n     \"  if (box._rows === undefined || box._m !== M || box._rows.length !== view.length) {\",\n     \"  if (box._rows === undefined) {\"),\n\n    (\"M6: 数字条不再高亮「刚添的那个 1」（图例承诺落空）\",\n     \"    if (st.cur.type === \\\"step\\\" && upto <= SHOW) {\\n      html[html.length - 1] = '<div class=\\\"digit new\\\">1</div>';\\n    }\",\n     \"\"),\n]\n\n\ndef run(cmd):\n    \"\"\"跑验证脚本。返回 (是否抓到, 进程结果)。\n\n    【注意】 判\"抓到\"不能只看返回码：验证脚本**自己崩了**（例如变异把文件写出了语法错误）\n    也是非零返回码，那属于**伪阳性** —— 变异本身无效，而不是断言有牙齿。\n    所以要求输出里出现明确的 `FAIL` 标记才算数。\n    \"\"\"\n    env = dict(os.environ)\n    env[\"PYTHONIOENCODING\"] = \"utf-8\"      # 子进程输出钉成 UTF-8，和下面的解码一致\n    p = subprocess.run(cmd, capture_output=True, text=True, encoding=\"utf-8\",\n                       errors=\"replace\", cwd=HERE, env=env)\n    out = (p.stdout or \"\") + (p.stderr or \"\")\n    marked = (\"FAIL\" in (p.stdout or \"\"))\n    crashed = (\"Traceback (most recent call last)\" in out)\n    return (p.returncode != 0 and marked and not crashed), p\n\n\ndef first_failure(out):\n    \"\"\"从验证脚本输出里挑第一条失败原因。\n\n    【注意】 要先看未 strip 的原始行再判断缩进 —— 先 strip 的话 startswith(\"  \") 永远为假。\n    \"\"\"\n    lines = (out or \"\").split(\"\\n\")\n    for line in lines:\n        if line.startswith(\"  \") and line.strip():\n            body = line.strip()\n            if body.startswith(\"FAIL\") or body.startswith(\"OK\"):\n                continue\n            return body[:95]\n    for line in lines:\n        if line.startswith(\"FAIL:\") or line.startswith(\"FAIL \"):\n            return line.strip()[:95]\n    return lines[0][:95] if lines else \"(无输出)\"\n\n\ndef write_exact(path, text):\n    \"\"\"按原样写回：**newline=\"\" 关闭换行翻译**（否则 LF 文件会被静默改成 CRLF）。\"\"\"\n    io.open(path, \"w\", encoding=\"utf-8\", newline=\"\").write(text)\n\n\ndef mutate_and_check(src_path, mutations, cmd, label):\n    original = io.open(src_path, encoding=\"utf-8\", newline=\"\").read()\n    nl = \"\\r\\n\" if \"\\r\\n\" in original else \"\\n\"\n    caught = 0\n    missed = []\n    try:\n        for name, frm, to in mutations:\n            frm_x = frm.replace(\"\\n\", nl)\n            to_x = to.replace(\"\\n\", nl)\n            if frm_x not in original:\n                print(\"  [SKIP] \" + name + \" —— 找不到锚点文本（代码改过？）\")\n                missed.append(name + \"（锚点失效）\")\n                continue\n            write_exact(src_path, original.replace(frm_x, to_x, 1))\n            failed, p = run(cmd)\n            write_exact(src_path, original)              # 立刻还原\n            if failed:\n                caught += 1\n                print(\"  [抓到] \" + name + \"  ->  \" + first_failure(p.stdout))\n            elif p.returncode != 0:\n                missed.append(name + \"（验证脚本崩溃，非断言失败）\")\n                print(\"  [可疑] \" + name + \"  <- 返回码 != 0 但无 FAIL 标记：\"\n                      \"验证脚本像是崩了，不能算断言抓到\")\n            else:\n                missed.append(name)\n                print(\"  [漏了] \" + name + \"  <- 这条断言没牙齿，要补强\")\n    finally:\n        write_exact(src_path, original)\n\n    failed, p = run(cmd)\n    restored = not failed\n    print(\"  \" + label + \" 变异捕获率: \" + str(caught) + \"/\" + str(len(mutations))\n          + \"；还原后: \" + (\"仍全绿 OK\" if restored else \"竟然 FAIL（没还原干净！）\"))\n    return caught, len(mutations), restored, missed\n\n\ndef main():\n    print(\"提交版（repunit.py <- verify_repunit.py）\")\n    c1, n1, r1, miss1 = mutate_and_check(PY_SRC, PY_MUTATIONS,\n                                         [sys.executable, PY_VERIFIER], \"提交版\")\n    print(\"\")\n    print(\"详细版（repunit_detailed.py <- verify_repunit.py）\")\n    c2, n2, r2, miss2 = mutate_and_check(DET_SRC, DET_MUTATIONS,\n                                         [sys.executable, PY_VERIFIER], \"详细版\")\n\n    c3, n3, r3, miss3 = 0, 0, True, []\n    js_verifier = os.path.join(HERE, \"verify_repunit_animation.js\")\n    html_src = os.path.join(HERE, \"repunit_animation.html\")\n    if os.path.exists(js_verifier) and os.path.exists(html_src):\n        print(\"\")\n        print(\"动画侧（repunit_animation.html <- verify_repunit_animation.js）\")\n        c3, n3, r3, miss3 = mutate_and_check(html_src, JS_MUTATIONS,\n                                             [\"node\", js_verifier], \"动画\")\n    else:\n        print(\"\")\n        print(\"（动画脚本还没生成，跳过动画侧变异）\")\n\n    all_missed = miss1 + miss2 + miss3\n    print(\"\")\n    if all_missed:\n        print(\"FAIL: 漏掉的变异 \" + str(len(all_missed)) + \" 个 -> 这些断言是装饰品：\")\n        for m in all_missed:\n            print(\"  - \" + m)\n        return 1\n    print(\"OK: 变异捕获率 \" + str(c1 + c2 + c3) + \"/\" + str(n1 + n2 + n3)\n          + \"（提交版 \" + str(c1) + \"/\" + str(n1)\n          + \"，详细版 \" + str(c2) + \"/\" + str(n2)\n          + \"，动画 \" + str(c3) + \"/\" + str(n3)\n          + \"）；还原后验证脚本均仍全绿\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}];
